fn br2_stage_recovery_sample_has_textured_draw(sample: &Br2StageRecoverySample) -> bool {
    sample.replay_ranges.iter().any(|range| {
        sample
            .words
            .get(range.start)
            .is_some_and(|word| looks_like_textured_primitive_opcode((word >> 24) as u8))
    })
}

