    fn push_mdec_dma_activity(&mut self, sample: MdecDmaActivitySample) {
        self.mdec_dma_activity.push(sample);
        if self.mdec_dma_activity.len() > MDEC_DMA_ACTIVITY_RECENT_LIMIT {
            let overflow = self.mdec_dma_activity.len() - MDEC_DMA_ACTIVITY_RECENT_LIMIT;
            self.mdec_dma_activity.drain(0..overflow);
        }
    }

    fn recent_dma_register_writes_json(&self, channel: usize, limit: usize) -> String {
        if limit == 0 {
            return String::new();
        }
        let mut samples = self
            .dma_activity
            .iter()
            .rev()
            .filter(|sample| sample.channel == channel && sample.kind == "register_write")
            .take(limit)
            .collect::<Vec<_>>();
        samples.reverse();
        samples
            .into_iter()
            .map(DmaActivitySample::json)
            .collect::<Vec<_>>()
            .join(",")
    }

    fn last_dma_register_write_json(&self, channel: usize) -> String {
        self.dma_activity
            .iter()
            .rev()
            .find(|sample| sample.channel == channel && sample.kind == "register_write")
            .map(DmaActivitySample::json)
            .unwrap_or_else(|| "null".to_string())
    }

    fn recent_dma_activity_counts_json(&self) -> String {
        let mut channels = self
            .dma_activity
            .iter()
            .map(|sample| sample.channel)
            .collect::<Vec<_>>();
        channels.sort_unstable();
        channels.dedup();

        channels
            .into_iter()
            .map(|channel| {
                let mut samples = 0u64;
                let mut register_writes = 0u64;
                let mut transfers = 0u64;
                let mut gpu_linked_list = 0u64;
                let mut gpu_block_write = 0u64;
                let mut gpu_read = 0u64;
                let mut otc_clear = 0u64;
                let mut last_vblank = None;
                let mut last_pc = None;

                for sample in self
                    .dma_activity
                    .iter()
                    .filter(|sample| sample.channel == channel)
                {
                    samples = samples.saturating_add(1);
                    last_vblank = Some(sample.vblank);
                    last_pc = sample.pc;
                    match sample.kind {
                        "register_write" => register_writes = register_writes.saturating_add(1),
                        "gpu_linked_list" => {
                            transfers = transfers.saturating_add(1);
                            gpu_linked_list = gpu_linked_list.saturating_add(1);
                        }
                        "gpu_block_write" => {
                            transfers = transfers.saturating_add(1);
                            gpu_block_write = gpu_block_write.saturating_add(1);
                        }
                        "gpu_read" => {
                            transfers = transfers.saturating_add(1);
                            gpu_read = gpu_read.saturating_add(1);
                        }
                        "otc_clear" => {
                            transfers = transfers.saturating_add(1);
                            otc_clear = otc_clear.saturating_add(1);
                        }
                        _ => transfers = transfers.saturating_add(1),
                    }
                }

                format!(
                    "{{\"channel\":{},\"samples\":{},\"register_writes\":{},\"transfers\":{},\"gpu_linked_list\":{},\"gpu_block_write\":{},\"gpu_read\":{},\"otc_clear\":{},\"last_vblank\":{},\"last_pc\":{},\"last_pc_hex\":{}}}",
                    channel,
                    samples,
                    register_writes,
                    transfers,
                    gpu_linked_list,
                    gpu_block_write,
                    gpu_read,
                    otc_clear,
                    optional_u64_json(last_vblank),
                    optional_u32_json(last_pc),
                    optional_u32_hex_json(last_pc)
                )
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn dma_lifetime_activity_json(&self) -> String {
        self.dma_lifetime_activity
            .iter()
            .enumerate()
            .filter(|(_, stats)| stats.samples > 0)
            .map(|(channel, stats)| stats.json(channel))
            .collect::<Vec<_>>()
            .join(",")
    }

    fn recent_otc_clear_ranges_json(&self, limit: usize) -> String {
        let mut samples = self
            .dma_activity
            .iter()
            .rev()
            .filter(|sample| sample.kind == "otc_clear")
            .take(limit)
            .collect::<Vec<_>>();
        samples.reverse();
        samples
            .into_iter()
            .filter_map(|sample| {
                let (low, high) = dma_activity_range_bounds(sample)?;
                Some(format!(
                    "{{\"vblank\":{},\"cycles\":{},\"start\":{},\"start_hex\":\"0x{:08x}\",\"end\":{},\"end_hex\":\"0x{:08x}\",\"low\":{},\"low_hex\":\"0x{:08x}\",\"high\":{},\"high_hex\":\"0x{:08x}\",\"words\":{},\"pc\":{},\"pc_hex\":{}}}",
                    sample.vblank,
                    sample.cycles,
                    sample.start.unwrap_or_default(),
                    sample.start.unwrap_or_default(),
                    sample.end.unwrap_or_default(),
                    sample.end.unwrap_or_default(),
                    low,
                    low,
                    high,
                    high,
                    sample.words,
                    optional_u32_json(sample.pc),
                    optional_u32_hex_json(sample.pc)
                ))
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn primitive_address_dma_relation_json(&self, address: u32) -> String {
        let gpu_start = self.gpu_linked_list_dma.last_start & 0x00ff_fffc;
        let gpu_first_node = self.gpu_linked_list_dma.last_first_node & 0x00ff_fffc;
        let gpu_start_distance = address.abs_diff(gpu_start);
        let gpu_first_node_distance = address.abs_diff(gpu_first_node);

        let latest_otc = self
            .dma_activity
            .iter()
            .rev()
            .find(|sample| sample.kind == "otc_clear")
            .and_then(|sample| {
                let (low, high) = dma_activity_range_bounds(sample)?;
                let inside = (low..=high).contains(&address);
                Some((
                    sample,
                    low,
                    high,
                    inside,
                    distance_to_range(address, low, high),
                ))
            });
        let nearest_otc = self
            .dma_activity
            .iter()
            .rev()
            .filter(|sample| sample.kind == "otc_clear")
            .take(DMA_OTC_RECENT_RANGE_LIMIT)
            .filter_map(|sample| {
                let (low, high) = dma_activity_range_bounds(sample)?;
                let inside = (low..=high).contains(&address);
                Some((
                    sample,
                    low,
                    high,
                    inside,
                    distance_to_range(address, low, high),
                ))
            })
            .min_by_key(|(_, _, _, inside, distance)| (!*inside, *distance));

        let (
            latest_otc_vblank,
            latest_otc_low,
            latest_otc_high,
            latest_otc_inside,
            latest_otc_distance,
        ) = latest_otc.map_or(
            (None, None, None, false, None),
            |(sample, low, high, inside, distance)| {
                (
                    Some(sample.vblank),
                    Some(low),
                    Some(high),
                    inside,
                    Some(distance),
                )
            },
        );
        let (
            nearest_otc_vblank,
            nearest_otc_low,
            nearest_otc_high,
            nearest_otc_inside,
            nearest_otc_distance,
        ) = nearest_otc.map_or(
            (None, None, None, false, None),
            |(sample, low, high, inside, distance)| {
                (
                    Some(sample.vblank),
                    Some(low),
                    Some(high),
                    inside,
                    Some(distance),
                )
            },
        );

        format!(
            "{{\"last_gpu_start\":{},\"last_gpu_start_hex\":\"0x{:08x}\",\"distance_to_last_gpu_start\":{},\"last_gpu_first_node\":{},\"last_gpu_first_node_hex\":\"0x{:08x}\",\"distance_to_last_gpu_first_node\":{},\"latest_otc_vblank\":{},\"latest_otc_low\":{},\"latest_otc_low_hex\":{},\"latest_otc_high\":{},\"latest_otc_high_hex\":{},\"inside_latest_otc\":{},\"distance_to_latest_otc\":{},\"nearest_otc_vblank\":{},\"nearest_otc_low\":{},\"nearest_otc_low_hex\":{},\"nearest_otc_high\":{},\"nearest_otc_high_hex\":{},\"inside_nearest_otc\":{},\"distance_to_nearest_otc\":{}}}",
            gpu_start,
            gpu_start,
            gpu_start_distance,
            gpu_first_node,
            gpu_first_node,
            gpu_first_node_distance,
            optional_u64_json(latest_otc_vblank),
            optional_u32_json(latest_otc_low),
            optional_u32_hex_json(latest_otc_low),
            optional_u32_json(latest_otc_high),
            optional_u32_hex_json(latest_otc_high),
            latest_otc_inside,
            optional_u32_json(latest_otc_distance),
            optional_u64_json(nearest_otc_vblank),
            optional_u32_json(nearest_otc_low),
            optional_u32_hex_json(nearest_otc_low),
            optional_u32_json(nearest_otc_high),
            optional_u32_hex_json(nearest_otc_high),
            nearest_otc_inside,
            optional_u32_json(nearest_otc_distance)
        )
    }

    fn recent_primitive_header_relations_json(&self, limit: usize) -> String {
        if limit == 0 {
            return String::new();
        }
        let linked_nodes = self
            .gpu_linked_list_dma
            .last_visited_nodes
            .iter()
            .map(|address| address & 0x00ff_fffc)
            .collect::<HashSet<_>>();
        self.primitive_ram_writes
            .recent_header_like_writes
            .iter()
            .rev()
            .take(limit)
            .filter_map(|write| {
                let word_count = write.value >> 24;
                let next = write.value & 0x00ff_ffff;
                let first_command = self.read_ram_u32_physical(write.address + 4)?;
                let opcode = (first_command >> 24) as u8;
                let sample = self.primitive_packet_candidate_sample(write.address, &linked_nodes);
                let linked = sample
                    .as_ref()
                    .is_some_and(|sample| sample.linked)
                    || linked_nodes.contains(&(write.address & 0x00ff_fffc));
                let command_write_vblank = sample
                    .as_ref()
                    .and_then(|sample| sample.command_write_vblank);
                let playfield_bounds = sample.as_ref().is_some_and(|sample| {
                    self.primitive_packet_has_playfield_draw_bounds(
                        sample.address,
                        sample.word_count,
                    )
                });
                Some(format!(
                    "{{\"address\":{},\"address_hex\":\"0x{:08x}\",\"value\":{},\"value_hex\":\"0x{:08x}\",\"word_count\":{},\"next\":{},\"next_hex\":\"0x{:06x}\",\"first_command\":{},\"first_command_hex\":\"0x{:08x}\",\"opcode\":{},\"opcode_hex\":\"0x{:02x}\",\"candidate\":{},\"linked\":{},\"draw_opcode\":{},\"playfield_bounds\":{},\"header_write_vblank\":{},\"command_write_vblank\":{},\"pc\":{},\"pc_hex\":{},\"cycles\":{},\"dma_relation\":{}}}",
                    write.address,
                    write.address,
                    write.value,
                    write.value,
                    word_count,
                    next,
                    next,
                    first_command,
                    first_command,
                    opcode,
                    opcode,
                    sample.is_some(),
                    linked,
                    looks_like_draw_primitive_opcode(opcode),
                    playfield_bounds,
                    write.vblank,
                    optional_u64_json(command_write_vblank),
                    optional_u32_json(write.pc),
                    optional_u32_hex_json(write.pc),
                    write.cycles,
                    self.primitive_address_dma_relation_json(write.address)
                ))
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn dma_channel_compact_json(&self, channel: usize) -> String {
        let Some(state) = self.io.dma.channel_state(channel) else {
            return "null".to_string();
        };
        let pending_cycles = self
            .pending_dma_completion_cycles
            .get(channel)
            .copied()
            .unwrap_or_default();
        format!(
            "{{\"channel\":{},\"madr\":{},\"madr_hex\":\"0x{:08x}\",\"bcr\":{},\"bcr_hex\":\"0x{:08x}\",\"chcr\":{},\"chcr_hex\":\"0x{:08x}\",\"pending_completion_cycles\":{}}}",
            channel,
            state.madr,
            state.madr,
            state.bcr,
            state.bcr,
            state.chcr,
            state.chcr,
            pending_cycles
        )
    }

    fn primitive_packet_scan_json(&self) -> String {
        let linked_nodes = self
            .gpu_linked_list_dma
            .last_visited_nodes
            .iter()
            .map(|address| address & 0x00ff_fffc)
            .collect::<HashSet<_>>();
        let mut candidates = 0u64;
        let mut linked_candidates = 0u64;
        let mut unlinked_candidates = 0u64;
        let mut candidate_words = 0u64;
        let mut linked_words = 0u64;
        let mut unlinked_words = 0u64;
        let mut opcode_counts = [0u64; 256];
        let mut linked_opcode_counts = [0u64; 256];
        let mut unlinked_opcode_counts = [0u64; 256];
        let mut linked_samples = Vec::new();
        let mut unlinked_samples = Vec::new();
        let current_vblank = self.vblank_count;
        let previous_vblank = self.vblank_count.saturating_sub(1);
        let mut current_vblank_candidates = 0u64;
        let mut previous_vblank_candidates = 0u64;
        let mut current_vblank_command_candidates = 0u64;
        let mut previous_vblank_command_candidates = 0u64;
        let mut current_vblank_linked_candidates = 0u64;
        let mut previous_vblank_linked_candidates = 0u64;

        let mut address = BR2_CHARACTER_MODEL_PACKET_START;
        while address.saturating_add(8) <= BR2_CHARACTER_MODEL_PACKET_END {
            if let Some(sample) = self.primitive_packet_candidate_sample(address, &linked_nodes) {
                let opcode_index = (sample.first_command >> 24) as usize;
                let words = u64::from(sample.word_count);
                candidates = candidates.saturating_add(1);
                candidate_words = candidate_words.saturating_add(words);
                opcode_counts[opcode_index] = opcode_counts[opcode_index].saturating_add(1);
                if sample.header_write_vblank == Some(current_vblank) {
                    current_vblank_candidates = current_vblank_candidates.saturating_add(1);
                    if sample.linked {
                        current_vblank_linked_candidates =
                            current_vblank_linked_candidates.saturating_add(1);
                    }
                }
                if sample.header_write_vblank == Some(previous_vblank) {
                    previous_vblank_candidates = previous_vblank_candidates.saturating_add(1);
                    if sample.linked {
                        previous_vblank_linked_candidates =
                            previous_vblank_linked_candidates.saturating_add(1);
                    }
                }
                if sample.command_write_vblank == Some(current_vblank) {
                    current_vblank_command_candidates =
                        current_vblank_command_candidates.saturating_add(1);
                }
                if sample.command_write_vblank == Some(previous_vblank) {
                    previous_vblank_command_candidates =
                        previous_vblank_command_candidates.saturating_add(1);
                }
                if sample.linked {
                    linked_candidates = linked_candidates.saturating_add(1);
                    linked_words = linked_words.saturating_add(words);
                    linked_opcode_counts[opcode_index] =
                        linked_opcode_counts[opcode_index].saturating_add(1);
                    if linked_samples.len() < PRIMITIVE_PACKET_SCAN_SAMPLE_LIMIT {
                        linked_samples.push(sample);
                    }
                } else {
                    unlinked_candidates = unlinked_candidates.saturating_add(1);
                    unlinked_words = unlinked_words.saturating_add(words);
                    unlinked_opcode_counts[opcode_index] =
                        unlinked_opcode_counts[opcode_index].saturating_add(1);
                    if unlinked_samples.len() < PRIMITIVE_PACKET_SCAN_SAMPLE_LIMIT {
                        unlinked_samples.push(sample);
                    }
                }
            }
            address = address.saturating_add(4);
        }

        let linked_samples_json = linked_samples
            .iter()
            .map(PrimitivePacketCandidateSample::json)
            .collect::<Vec<_>>()
            .join(",");
        let unlinked_samples_json = unlinked_samples
            .iter()
            .map(PrimitivePacketCandidateSample::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"range_start\":\"0x{:08x}\",\"range_end\":\"0x{:08x}\",\"max_packet_words\":{},\"current_vblank\":{},\"previous_vblank\":{},\"last_dma_visited_nodes\":{},\"candidates\":{},\"linked_candidates\":{},\"unlinked_candidates\":{},\"current_vblank_candidates\":{},\"current_vblank_command_candidates\":{},\"current_vblank_linked_candidates\":{},\"previous_vblank_candidates\":{},\"previous_vblank_command_candidates\":{},\"previous_vblank_linked_candidates\":{},\"candidate_words\":{},\"linked_words\":{},\"unlinked_words\":{},\"opcode_counts\":[{}],\"linked_opcode_counts\":[{}],\"unlinked_opcode_counts\":[{}],\"linked_samples\":[{}],\"unlinked_samples\":[{}]}}",
            BR2_PRIMITIVE_RAM_START,
            BR2_PRIMITIVE_RAM_END,
            PRIMITIVE_PACKET_MAX_WORDS,
            current_vblank,
            previous_vblank,
            linked_nodes.len(),
            candidates,
            linked_candidates,
            unlinked_candidates,
            current_vblank_candidates,
            current_vblank_command_candidates,
            current_vblank_linked_candidates,
            previous_vblank_candidates,
            previous_vblank_command_candidates,
            previous_vblank_linked_candidates,
            candidate_words,
            linked_words,
            unlinked_words,
            u64_command_opcode_counts_json(&opcode_counts),
            u64_command_opcode_counts_json(&linked_opcode_counts),
            u64_command_opcode_counts_json(&unlinked_opcode_counts),
            linked_samples_json,
            unlinked_samples_json
        )
    }

    fn primitive_packet_scan_compact_json(&self) -> String {
        let linked_nodes = self
            .gpu_linked_list_dma
            .last_visited_nodes
            .iter()
            .map(|address| address & 0x00ff_fffc)
            .collect::<HashSet<_>>();
        let current_vblank = self.vblank_count;
        let previous_vblank = self.vblank_count.saturating_sub(1);
        let min_vblank = self
            .vblank_count
            .saturating_sub(BR2_UNLINKED_PRIMITIVE_REPLAY_VBLANK_WINDOW);
        let mut candidates = 0u64;
        let mut linked_candidates = 0u64;
        let mut unlinked_candidates = 0u64;
        let mut draw_candidates = 0u64;
        let mut playfield_candidates = 0u64;
        let mut recent_command_candidates = 0u64;
        let mut current_vblank_candidates = 0u64;
        let mut previous_vblank_candidates = 0u64;
        let mut newest_header_vblank = 0u64;
        let mut newest_command_vblank = 0u64;

        let mut address = BR2_PRIMITIVE_RAM_START;
        while address.saturating_add(8) <= BR2_PRIMITIVE_RAM_END {
            if let Some(sample) = self.primitive_packet_candidate_sample(address, &linked_nodes) {
                candidates = candidates.saturating_add(1);
                if sample.linked {
                    linked_candidates = linked_candidates.saturating_add(1);
                } else {
                    unlinked_candidates = unlinked_candidates.saturating_add(1);
                }
                let opcode = (sample.first_command >> 24) as u8;
                if looks_like_draw_primitive_opcode(opcode) {
                    draw_candidates = draw_candidates.saturating_add(1);
                }
                if looks_like_draw_primitive_opcode(opcode)
                    && self.primitive_packet_has_playfield_draw_bounds(address, sample.word_count)
                {
                    playfield_candidates = playfield_candidates.saturating_add(1);
                }
                if sample
                    .command_write_vblank
                    .is_some_and(|vblank| vblank >= min_vblank)
                {
                    recent_command_candidates = recent_command_candidates.saturating_add(1);
                }
                if sample.header_write_vblank == Some(current_vblank) {
                    current_vblank_candidates = current_vblank_candidates.saturating_add(1);
                }
                if sample.header_write_vblank == Some(previous_vblank) {
                    previous_vblank_candidates = previous_vblank_candidates.saturating_add(1);
                }
                if let Some(vblank) = sample.header_write_vblank {
                    newest_header_vblank = newest_header_vblank.max(vblank);
                }
                if let Some(vblank) = sample.command_write_vblank {
                    newest_command_vblank = newest_command_vblank.max(vblank);
                }
            }
            address = address.saturating_add(4);
        }

        format!(
            "{{\"last_dma_visited_nodes\":{},\"candidates\":{},\"linked_candidates\":{},\"unlinked_candidates\":{},\"draw_candidates\":{},\"playfield_candidates\":{},\"recent_command_candidates\":{},\"current_vblank_candidates\":{},\"previous_vblank_candidates\":{},\"newest_header_vblank\":{},\"newest_command_vblank\":{},\"min_recent_vblank\":{}}}",
            linked_nodes.len(),
            candidates,
            linked_candidates,
            unlinked_candidates,
            draw_candidates,
            playfield_candidates,
            recent_command_candidates,
            current_vblank_candidates,
            previous_vblank_candidates,
            newest_header_vblank,
            newest_command_vblank,
            min_vblank
        )
    }

    fn br2_character_model_packets_json(&self) -> String {
        let linked_nodes = self
            .gpu_linked_list_dma
            .last_visited_nodes
            .iter()
            .map(|address| address & 0x00ff_fffc)
            .collect::<HashSet<_>>();
        let mut region_packet_count = 0u64;
        let mut region_linked_packet_count = 0u64;
        let mut region_draw_packet_count = 0u64;
        let mut region_textured_packet_count = 0u64;
        let mut low_ram_packet_count = 0u64;
        let mut low_ram_linked_packet_count = 0u64;
        let mut low_ram_draw_packet_count = 0u64;
        let mut low_ram_textured_packet_count = 0u64;
        let mut high_ram_packet_count = 0u64;
        let mut high_ram_linked_packet_count = 0u64;
        let mut high_ram_draw_packet_count = 0u64;
        let mut high_ram_textured_packet_count = 0u64;
        let mut descriptor_counts = HashMap::<(u16, u16), (u64, u64)>::new();
        let mut recent_textured_samples = Vec::<(u64, u32, String)>::new();
        let mut low_ram_textured_samples = Vec::<(u64, u32, String)>::new();
        let mut low_ram_model_candidate_samples = Vec::<(u64, u32, usize, String)>::new();
        let mut beast_candidate_samples = Vec::<(u64, u32, String)>::new();
        let mut packet_count = 0u64;
        let mut linked_packet_count = 0u64;
        let mut newest_header_vblank = None;
        let mut newest_command_vblank = None;
        let mut min_address = None;
        let mut max_address = None;
        let mut samples = Vec::new();

        for (range_start, range_end) in [
            (
                BR2_CHARACTER_MODEL_LOW_RAM_START,
                BR2_CHARACTER_MODEL_LOW_RAM_END,
            ),
            (BR2_PRIMITIVE_RAM_START, BR2_PRIMITIVE_RAM_END),
        ] {
            let low_ram = range_start == BR2_CHARACTER_MODEL_LOW_RAM_START;
            let mut address = range_start;
            while address.saturating_add(8) <= range_end {
                let Some(packet) = self.primitive_packet_candidate_sample(address, &linked_nodes)
                else {
                    address = address.saturating_add(4);
                    continue;
                };
                region_packet_count = region_packet_count.saturating_add(1);
                region_linked_packet_count =
                    region_linked_packet_count.saturating_add(u64::from(packet.linked));
                if low_ram {
                    low_ram_packet_count = low_ram_packet_count.saturating_add(1);
                    low_ram_linked_packet_count =
                        low_ram_linked_packet_count.saturating_add(u64::from(packet.linked));
                } else {
                    high_ram_packet_count = high_ram_packet_count.saturating_add(1);
                    high_ram_linked_packet_count =
                        high_ram_linked_packet_count.saturating_add(u64::from(packet.linked));
                }
                if looks_like_draw_primitive_opcode((packet.first_command >> 24) as u8) {
                    region_draw_packet_count = region_draw_packet_count.saturating_add(1);
                    if low_ram {
                        low_ram_draw_packet_count = low_ram_draw_packet_count.saturating_add(1);
                    } else {
                        high_ram_draw_packet_count = high_ram_draw_packet_count.saturating_add(1);
                    }
                }
                let words = self.primitive_packet_command_words(address, packet.word_count);
                let mut offset = 0usize;
                let mut matched = None;
                let mut first_textured = None;
                while offset < words.len() {
                    let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
                        break;
                    };
                    if command_words == 0 || offset + command_words > words.len() {
                        break;
                    }
                    let command = &words[offset..offset + command_words];
                    if let Some((texture_page, clut)) = gp0_command_texture_descriptor(command) {
                        first_textured.get_or_insert((texture_page, clut, command));
                        let entry = descriptor_counts
                            .entry((texture_page, clut))
                            .or_insert((0, 0));
                        entry.0 = entry.0.saturating_add(1);
                        entry.1 = entry.1.max(packet.command_write_vblank.unwrap_or(0));
                        if low_ram
                            && br2_low_ram_character_model_descriptor(address, (texture_page, clut))
                        {
                            let freshness = packet
                                .command_write_vblank
                                .or(packet.header_write_vblank)
                                .unwrap_or(0);
                            let bounds = gp0_command_draw_bounds(command);
                            let evaluation = self
                                .gpu_current_br2_character_model_draw_evaluation(address, command);
                            low_ram_model_candidate_samples.push((
                                freshness,
                                address,
                                offset,
                                format!(
                                    "{{\"address\":{},\"address_hex\":\"0x{:08x}\",\"command_address\":{},\"command_address_hex\":\"0x{:08x}\",\"command_offset\":{},\"linked\":{},\"word_count\":{},\"texture_page\":{},\"texture_page_hex\":\"0x{:04x}\",\"clut\":{},\"clut_hex\":\"0x{:04x}\",\"clut_row\":{},\"header_write_vblank\":{},\"command_write_vblank\":{},\"bounds\":{},\"model_bounds_coherent\":{},\"evaluation\":\"{}\",\"words\":[{}],\"word_writes\":[{}]}}",
                                    packet.address,
                                    packet.address,
                                    packet.address + 4 + offset as u32 * 4,
                                    packet.address + 4 + offset as u32 * 4,
                                    offset,
                                    packet.linked,
                                    packet.word_count,
                                    texture_page,
                                    texture_page,
                                    clut,
                                    clut,
                                    gp0_clut_row(clut),
                                    optional_u64_json(packet.header_write_vblank),
                                    optional_u64_json(packet.command_write_vblank),
                                    bounds.map_or_else(
                                        || "null".to_string(),
                                        Gp0DrawBounds::json
                                    ),
                                    bounds.is_some_and(
                                        br2_alternate_character_model_bounds_are_coherent
                                    ),
                                    evaluation.map_or_else(
                                        |reason| reason.as_str(),
                                        |_| "accepted"
                                    ),
                                    command
                                        .iter()
                                        .map(|word| format!("\"0x{word:08x}\""))
                                        .collect::<Vec<_>>()
                                        .join(","),
                                    self.primitive_packet_word_writes_json(
                                        packet.address,
                                        packet.word_count
                                    )
                                ),
                            ));
                        }
                        if gp0_command_is_br2_character_model_for_packet(address, command) {
                            matched = Some((texture_page, clut, command));
                        }
                    }
                    offset += command_words;
                }

                if let Some((texture_page, clut, command)) = first_textured {
                    region_textured_packet_count = region_textured_packet_count.saturating_add(1);
                    if low_ram {
                        low_ram_textured_packet_count =
                            low_ram_textured_packet_count.saturating_add(1);
                    } else {
                        high_ram_textured_packet_count =
                            high_ram_textured_packet_count.saturating_add(1);
                    }
                    let bounds = gp0_command_draw_bounds(command);
                    let freshness = packet
                        .command_write_vblank
                        .or(packet.header_write_vblank)
                        .unwrap_or(0);
                    let sample_json = format!(
                        "{{\"address\":{},\"address_hex\":\"0x{:08x}\",\"linked\":{},\"word_count\":{},\"opcode\":{},\"opcode_hex\":\"0x{:02x}\",\"texture_page\":{},\"texture_page_hex\":\"0x{:04x}\",\"clut\":{},\"clut_hex\":\"0x{:04x}\",\"header_write_vblank\":{},\"command_write_vblank\":{},\"bounds\":{},\"next\":{},\"next_hex\":\"0x{:06x}\",\"words\":[{}],\"word_writes\":[{}]}}",
                        packet.address,
                        packet.address,
                        packet.linked,
                        packet.word_count,
                        command[0] >> 24,
                        command[0] >> 24,
                        texture_page,
                        texture_page,
                        clut,
                        clut,
                        optional_u64_json(packet.header_write_vblank),
                        optional_u64_json(packet.command_write_vblank),
                        bounds.map_or_else(|| "null".to_string(), Gp0DrawBounds::json),
                        packet.next,
                        packet.next,
                        words
                            .iter()
                            .map(|word| format!("\"0x{word:08x}\""))
                            .collect::<Vec<_>>()
                            .join(","),
                        self.primitive_packet_word_writes_json(packet.address, packet.word_count)
                    );
                    recent_textured_samples.push((freshness, packet.address, sample_json.clone()));
                    if low_ram {
                        low_ram_textured_samples.push((
                            freshness,
                            packet.address,
                            sample_json.clone(),
                        ));
                    }
                    if br2_beast_character_model_candidate_descriptor((texture_page, clut)) {
                        beast_candidate_samples.push((freshness, packet.address, sample_json));
                    }
                }

                let Some((texture_page, clut, command)) = matched else {
                    address = address.saturating_add(4);
                    continue;
                };
                packet_count = packet_count.saturating_add(1);
                linked_packet_count = linked_packet_count.saturating_add(u64::from(packet.linked));
                min_address =
                    Some(min_address.map_or(address, |current: u32| current.min(address)));
                max_address =
                    Some(max_address.map_or(address, |current: u32| current.max(address)));
                if let Some(vblank) = packet.header_write_vblank {
                    newest_header_vblank = Some(
                        newest_header_vblank.map_or(vblank, |current: u64| current.max(vblank)),
                    );
                }
                if let Some(vblank) = packet.command_write_vblank {
                    newest_command_vblank = Some(
                        newest_command_vblank.map_or(vblank, |current: u64| current.max(vblank)),
                    );
                }

                if samples.len() < BR2_CHARACTER_MODEL_PACKET_SAMPLE_LIMIT {
                    let bounds = gp0_command_draw_bounds(command);
                    let reject_reason = gp0_command_replay_draw_reject_reason(command)
                        .map_or_else(|| "null".to_string(), |reason| format!("\"{reason:?}\""));
                    samples.push(format!(
                        "{{\"address\":{},\"address_hex\":\"0x{:08x}\",\"header\":{},\"header_hex\":\"0x{:08x}\",\"next\":{},\"next_hex\":\"0x{:06x}\",\"linked\":{},\"word_count\":{},\"opcode\":{},\"opcode_hex\":\"0x{:02x}\",\"texture_page\":{},\"texture_page_hex\":\"0x{:04x}\",\"clut\":{},\"clut_hex\":\"0x{:04x}\",\"header_write_vblank\":{},\"command_write_vblank\":{},\"bounds\":{},\"replay_reject_reason\":{},\"dma_relation\":{},\"word_writes\":[{}]}}",
                        packet.address,
                        packet.address,
                        packet.header,
                        packet.header,
                        packet.next,
                        packet.next,
                        packet.linked,
                        packet.word_count,
                        command[0] >> 24,
                        command[0] >> 24,
                        texture_page,
                        texture_page,
                        clut,
                        clut,
                        optional_u64_json(packet.header_write_vblank),
                        optional_u64_json(packet.command_write_vblank),
                        bounds.map_or_else(|| "null".to_string(), Gp0DrawBounds::json),
                        reject_reason,
                        self.primitive_address_dma_relation_json(packet.address),
                        self.primitive_packet_word_writes_json(packet.address, packet.word_count)
                    ));
                }
                address = address.saturating_add(4);
            }
        }

        let mut descriptor_counts = descriptor_counts.into_iter().collect::<Vec<_>>();
        descriptor_counts.sort_unstable_by(|left, right| {
            right
                .1
                .0
                .cmp(&left.1.0)
                .then_with(|| right.1.1.cmp(&left.1.1))
                .then_with(|| left.0.cmp(&right.0))
        });
        let descriptor_counts = descriptor_counts
            .into_iter()
            .take(32)
            .map(|((texture_page, clut), (count, newest_command_vblank))| {
                format!(
                    "{{\"texture_page\":{},\"texture_page_hex\":\"0x{:04x}\",\"clut\":{},\"clut_hex\":\"0x{:04x}\",\"count\":{},\"newest_command_vblank\":{}}}",
                    texture_page,
                    texture_page,
                    clut,
                    clut,
                    count,
                    newest_command_vblank
                )
            })
            .collect::<Vec<_>>()
            .join(",");
        recent_textured_samples.sort_unstable_by(|left, right| {
            right.0.cmp(&left.0).then_with(|| right.1.cmp(&left.1))
        });
        let recent_textured_samples = recent_textured_samples
            .into_iter()
            .take(BR2_CHARACTER_MODEL_PACKET_SAMPLE_LIMIT)
            .map(|(_, _, json)| json)
            .collect::<Vec<_>>()
            .join(",");
        low_ram_textured_samples.sort_unstable_by(|left, right| {
            right.0.cmp(&left.0).then_with(|| right.1.cmp(&left.1))
        });
        let low_ram_textured_samples = low_ram_textured_samples
            .into_iter()
            .take(BR2_CHARACTER_MODEL_PACKET_SAMPLE_LIMIT)
            .map(|(_, _, json)| json)
            .collect::<Vec<_>>()
            .join(",");
        low_ram_model_candidate_samples.sort_unstable_by(|left, right| {
            right
                .0
                .cmp(&left.0)
                .then_with(|| right.1.cmp(&left.1))
                .then_with(|| right.2.cmp(&left.2))
        });
        let low_ram_model_candidate_samples = low_ram_model_candidate_samples
            .into_iter()
            .take(BR2_CHARACTER_MODEL_PACKET_SAMPLE_LIMIT * 4)
            .map(|(_, _, _, json)| json)
            .collect::<Vec<_>>()
            .join(",");
        beast_candidate_samples.sort_unstable_by(|left, right| {
            right.0.cmp(&left.0).then_with(|| right.1.cmp(&left.1))
        });
        let beast_candidate_samples = beast_candidate_samples
            .into_iter()
            .take(BR2_CHARACTER_MODEL_PACKET_SAMPLE_LIMIT * 4)
            .map(|(_, _, json)| json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"low_ram_range_start\":\"0x{:08x}\",\"low_ram_range_end\":\"0x{:08x}\",\"high_ram_range_start\":\"0x{:08x}\",\"high_ram_range_end\":\"0x{:08x}\",\"texture_page\":\"0x{:04x}\",\"cluts\":[\"0x{:04x}\",\"0x{:04x}\",\"0x{:04x}\",\"0x{:04x}\",\"0x{:04x}\"],\"current_vblank\":{},\"region_packets\":{},\"region_linked_packets\":{},\"region_unlinked_packets\":{},\"region_draw_packets\":{},\"region_textured_packets\":{},\"low_ram_packets\":{},\"low_ram_linked_packets\":{},\"low_ram_unlinked_packets\":{},\"low_ram_draw_packets\":{},\"low_ram_textured_packets\":{},\"high_ram_packets\":{},\"high_ram_linked_packets\":{},\"high_ram_unlinked_packets\":{},\"high_ram_draw_packets\":{},\"high_ram_textured_packets\":{},\"descriptor_counts\":[{}],\"recent_textured_samples\":[{}],\"low_ram_recent_textured_samples\":[{}],\"low_ram_model_candidate_samples\":[{}],\"beast_candidate_samples\":[{}],\"packets\":{},\"linked_packets\":{},\"unlinked_packets\":{},\"min_address\":{},\"min_address_hex\":{},\"max_address\":{},\"max_address_hex\":{},\"newest_header_vblank\":{},\"newest_command_vblank\":{},\"samples\":[{}]}}",
            BR2_CHARACTER_MODEL_LOW_RAM_START,
            BR2_CHARACTER_MODEL_LOW_RAM_END,
            BR2_PRIMITIVE_RAM_START,
            BR2_PRIMITIVE_RAM_END,
            BR2_CHARACTER_MODEL_TEXTURE_PAGE,
            BR2_CHARACTER_MODEL_CLUTS[0],
            BR2_CHARACTER_MODEL_CLUTS[1],
            BR2_CHARACTER_MODEL_CLUTS[2],
            BR2_CHARACTER_MODEL_CLUTS[3],
            BR2_CHARACTER_MODEL_CLUTS[4],
            self.vblank_count,
            region_packet_count,
            region_linked_packet_count,
            region_packet_count.saturating_sub(region_linked_packet_count),
            region_draw_packet_count,
            region_textured_packet_count,
            low_ram_packet_count,
            low_ram_linked_packet_count,
            low_ram_packet_count.saturating_sub(low_ram_linked_packet_count),
            low_ram_draw_packet_count,
            low_ram_textured_packet_count,
            high_ram_packet_count,
            high_ram_linked_packet_count,
            high_ram_packet_count.saturating_sub(high_ram_linked_packet_count),
            high_ram_draw_packet_count,
            high_ram_textured_packet_count,
            descriptor_counts,
            recent_textured_samples,
            low_ram_textured_samples,
            low_ram_model_candidate_samples,
            beast_candidate_samples,
            packet_count,
            linked_packet_count,
            packet_count.saturating_sub(linked_packet_count),
            optional_u32_json(min_address),
            optional_u32_hex_json(min_address),
            optional_u32_json(max_address),
            optional_u32_hex_json(max_address),
            optional_u64_json(newest_header_vblank),
            optional_u64_json(newest_command_vblank),
            samples.join(",")
        )
    }

    fn unlinked_primitive_replay_candidate_diagnostics_json(&self, limit: usize) -> String {
        if limit == 0 {
            return String::new();
        }

        let linked_nodes = self
            .gpu_linked_list_dma
            .last_visited_nodes
            .iter()
            .map(|address| address & 0x00ff_fffc)
            .collect::<HashSet<_>>();
        let min_vblank = self
            .vblank_count
            .saturating_sub(BR2_UNLINKED_PRIMITIVE_REPLAY_VBLANK_WINDOW);
        let candidates =
            self.collect_unlinked_primitive_replay_candidates(&linked_nodes, Some(min_vblank));
        self.unlinked_primitive_replay_order(&candidates, &linked_nodes)
            .into_iter()
            .take(limit)
            .filter_map(|candidate| {
                self.primitive_replay_candidate_diagnostic_json(candidate, &linked_nodes)
            })
            .collect::<Vec<_>>()
            .join(",")
    }

    fn primitive_replay_candidate_diagnostic_json(
        &self,
        candidate: PrimitiveReplayCandidate,
        linked_nodes: &HashSet<u32>,
    ) -> Option<String> {
        let sample = self.primitive_packet_candidate_sample(candidate.address, linked_nodes)?;
        let command_words = self.primitive_packet_command_words(sample.address, sample.word_count);
        let safe_draw_ranges = gp0_replay_safe_draw_command_ranges(&command_words);
        let safe_state_ranges = gp0_replay_safe_state_command_ranges(&command_words);
        let command_word_count = command_words.len();
        let command_words = command_words
            .iter()
            .map(|word| format!("\"0x{word:08x}\""))
            .collect::<Vec<_>>()
            .join(",");
        let opcode = (sample.first_command >> 24) as u8;
        Some(format!(
            "{{\"address\":{},\"address_hex\":\"0x{:08x}\",\"priority\":{},\"vblank\":{},\"linked\":{},\"word_count\":{},\"command_word_count\":{},\"next\":{},\"next_hex\":\"0x{:06x}\",\"opcode\":{},\"opcode_hex\":\"0x{:02x}\",\"draw_opcode\":{},\"textured_opcode\":{},\"playfield_bounds\":{},\"safe_draw_ranges\":[{}],\"safe_state_ranges\":[{}],\"header_write_vblank\":{},\"command_write_vblank\":{},\"dma_relation\":{},\"words\":[{}]}}",
            candidate.address,
            candidate.address,
            candidate.priority,
            candidate.vblank,
            sample.linked,
            sample.word_count,
            command_word_count,
            sample.next,
            sample.next,
            opcode,
            opcode,
            looks_like_draw_primitive_opcode(opcode),
            looks_like_textured_primitive_opcode(opcode),
            self.primitive_packet_has_playfield_draw_bounds(sample.address, sample.word_count),
            ranges_json(&safe_draw_ranges),
            ranges_json(&safe_state_ranges),
            optional_u64_json(sample.header_write_vblank),
            optional_u64_json(sample.command_write_vblank),
            self.primitive_address_dma_relation_json(sample.address),
            command_words
        ))
    }

    fn primitive_packet_candidate_sample(
        &self,
        address: u32,
        linked_nodes: &HashSet<u32>,
    ) -> Option<PrimitivePacketCandidateSample> {
        let range_end = br2_tracked_primitive_range_end(address)?;
        let header = self.read_ram_u32_physical(address)?;
        let word_count = header >> 24;
        if !(1..=PRIMITIVE_PACKET_MAX_WORDS).contains(&word_count) {
            return None;
        }

        let packet_end = address
            .checked_add(4)?
            .checked_add(word_count.checked_mul(4)?)?;
        if packet_end > range_end {
            return None;
        }

        let next = header & 0x00ff_ffff;
        if !primitive_packet_next_plausible(next) {
            return None;
        }

        let first_command = self.read_ram_u32_physical(address + 4)?;
        let opcode = (first_command >> 24) as u8;
        if !looks_like_gp0_command_opcode(opcode) {
            return None;
        }

        if !self.primitive_packet_words_plausible(address, word_count) {
            return None;
        }

        Some(PrimitivePacketCandidateSample {
            address,
            header,
            word_count,
            next,
            linked: linked_nodes.contains(&(address & 0x00ff_fffc)),
            first_command,
            header_write_vblank: self.primitive_ram_writes.header_write_vblank(address),
            command_write_vblank: self.packet_command_write_vblank(address, word_count),
        })
    }

    fn packet_command_write_vblank(&self, address: u32, word_count: u32) -> Option<u64> {
        let mut latest = None;
        for index in 0..word_count {
            let command_address = address + 4 + index * 4;
            if let Some(vblank) = self.primitive_ram_writes.word_write_vblank(command_address) {
                latest = Some(latest.map_or(vblank, |current: u64| current.max(vblank)));
            }
        }
        latest
    }

    fn primitive_packet_word_writes_json(&self, address: u32, word_count: u32) -> String {
        let samples = (0..=word_count)
            .filter_map(|index| {
                self.primitive_ram_writes
                    .word_write_sample(address.saturating_add(index.saturating_mul(4)))
            })
            .collect::<Vec<_>>();
        primitive_ram_write_samples_json(&samples)
    }

    fn primitive_packet_words_plausible(&self, address: u32, word_count: u32) -> bool {
        let mut commands = Vec::with_capacity(word_count as usize);
        for index in 0..word_count {
            let Some(command) = self.read_ram_u32_physical(address + 4 + index * 4) else {
                return false;
            };
            commands.push(command);
        }

        let mut offset = 0usize;
        while offset < commands.len() {
            let Some(command_words) = gp0_command_word_count(&commands[offset..]) else {
                return false;
            };
            if command_words == 0 || offset + command_words > commands.len() {
                return false;
            }
            offset += command_words;
        }
        true
    }

    fn primitive_packet_has_playfield_draw_bounds(&self, address: u32, word_count: u32) -> bool {
        let mut commands = Vec::with_capacity(word_count as usize);
        for index in 0..word_count {
            let Some(command) = self.read_ram_u32_physical(address + 4 + index * 4) else {
                return false;
            };
            commands.push(command);
        }

        let mut offset = 0usize;
        while offset < commands.len() {
            let Some(command_words) = gp0_command_word_count(&commands[offset..]) else {
                return false;
            };
            if command_words == 0 || offset + command_words > commands.len() {
                return false;
            }
            if gp0_command_is_replay_safe_draw(&commands[offset..offset + command_words]) {
                return true;
            }
            offset += command_words;
        }
        false
    }

