#[cfg(test)]
fn gp0_br2_character_model_replay_command_ranges(words: &[u32]) -> Vec<std::ops::Range<usize>> {
    gp0_br2_character_model_replay_command_ranges_for_packet(0, words)
}

fn gp0_br2_character_model_replay_command_ranges_for_packet(
    packet_address: u32,
    words: &[u32],
) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut offset = 0;
    let mut pending_state_start = None;
    while offset < words.len() {
        let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
            break;
        };
        if command_words == 0 || offset + command_words > words.len() {
            break;
        }
        let end = offset + command_words;
        let command = &words[offset..end];

        if gp0_command_is_replay_safe_state(command) {
            pending_state_start.get_or_insert(offset);
            offset = end;
            continue;
        }

        let model_texture = gp0_command_is_br2_character_model_for_packet(packet_address, command);
        let reject_reason = gp0_command_replay_draw_reject_reason(command);
        let clean_model_atlas_false_positive = model_texture
            && matches!(
                reject_reason,
                Some(
                    Gp0ReplayDrawRejectReason::CommandTextureContamination
                        | Gp0ReplayDrawRejectReason::TitleOverlayAtlas
                        | Gp0ReplayDrawRejectReason::Br2StageTransitionAtlas
                )
            );
        let model_atlas_strip_false_positive = model_texture
            && gp0_command_draw_bounds(command).is_some_and(|bounds| {
                gp0_command_is_br2_current_otc_model_atlas_strip_false_positive_for_packet(
                    packet_address,
                    command,
                    bounds,
                )
            });
        let model_uv_padding_pointer_false_positive = model_texture
            && reject_reason == Some(Gp0ReplayDrawRejectReason::PrimitivePointerContamination)
            && !model_atlas_strip_false_positive
            && gp0_command_is_valid_br2_character_model_draw_for_packet(packet_address, command)
            && gp0_br2_character_model_pointer_contamination_is_uv_padding_only_for_packet(
                packet_address,
                command,
            );
        if !model_atlas_strip_false_positive
            && (reject_reason.is_none()
                || clean_model_atlas_false_positive
                || model_uv_padding_pointer_false_positive)
        {
            ranges.push(pending_state_start.take().unwrap_or(offset)..end);
        } else {
            pending_state_start = None;
        }
        offset = end;
    }
    ranges
}

#[cfg(test)]
fn gp0_br2_stage_recovery_command_ranges(words: &[u32]) -> Vec<std::ops::Range<usize>> {
    gp0_br2_stage_recovery_command_ranges_with_drawing_offset(words, (0, 0))
}

fn gp0_br2_stage_recovery_command_ranges_with_drawing_offset(
    words: &[u32],
    initial_drawing_offset: (i32, i32),
) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut offset = 0;
    let mut pending_state_start = None;
    let mut drawing_offset = initial_drawing_offset;
    while offset < words.len() {
        let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
            break;
        };
        if command_words == 0 || offset + command_words > words.len() {
            break;
        }
        let end = offset + command_words;
        let command = &words[offset..end];

        if gp0_command_is_replay_safe_state(command) {
            pending_state_start.get_or_insert(offset);
            if command[0] >> 24 == 0xe5 {
                drawing_offset = gp0_drawing_offset_xy(command[0]);
            }
            offset = end;
            continue;
        }

        let stage_texture =
            gp0_command_texture_descriptor(command).is_some_and(|(texture_page, clut)| {
                br2_reused_texture_page_matches(texture_page, BR2_CHARACTER_MODEL_TEXTURE_PAGE)
                    && BR2_STAGE_TEXTURE_CLUTS.contains(&clut)
            });
        let character_model_texture =
            gp0_command_texture_descriptor(command).is_some_and(br2_character_model_texture);
        let status_glyph_tile =
            gp0_command_is_br2_status_glyph_tile_with_drawing_offset(command, drawing_offset);
        let non_gameplay_high_bank_atlas = gp0_command_is_br2_non_gameplay_high_bank_atlas(command);
        let reject_reason =
            gp0_command_replay_draw_reject_reason_with_state(command, None, drawing_offset);
        let clean_stage_texture_false_positive = stage_texture
            && matches!(
                reject_reason,
                Some(
                    Gp0ReplayDrawRejectReason::CommandTextureContamination
                        | Gp0ReplayDrawRejectReason::PrimitivePointerContamination
                        | Gp0ReplayDrawRejectReason::TitleOverlayAtlas
                        | Gp0ReplayDrawRejectReason::Br2StageTransitionAtlas
                )
            );
        if !character_model_texture
            && !status_glyph_tile
            && !non_gameplay_high_bank_atlas
            && (reject_reason.is_none() || clean_stage_texture_false_positive)
        {
            ranges.push(pending_state_start.take().unwrap_or(offset)..end);
        } else {
            pending_state_start = None;
        }
        offset = end;
    }
    ranges
}

fn repair_br2_recovered_stage_rectangular_quad(words: &mut [u32]) -> bool {
    if words.len() != 9
        || (words[0] >> 24) as u8 != 0x2d
        || gp0_command_texture_descriptor(words) != Some((0x000e, 0x781e))
    {
        return false;
    }

    let coordinate = |word: u32| ((word & 0xffff) as u16, (word >> 16) as u16);
    let texture_coordinate = |word: u32| ((word & 0xff) as u8, ((word >> 8) & 0xff) as u8);
    let (a_x, a_y) = coordinate(words[1]);
    let (b_x, b_y) = coordinate(words[3]);
    let (c_x, c_y) = coordinate(words[5]);
    let (d_x, d_y) = coordinate(words[7]);
    let (a_u, a_v) = texture_coordinate(words[2]);
    let (b_u, b_v) = texture_coordinate(words[4]);
    let (c_u, c_v) = texture_coordinate(words[6]);
    let (d_u, d_v) = texture_coordinate(words[8]);

    let texture_rectangle = a_u.abs_diff(c_u) <= 4
        && b_u.abs_diff(d_u) <= 4
        && a_v == b_v
        && c_v == d_v
        && a_u != b_u
        && a_v != c_v;
    if !texture_rectangle {
        return false;
    }

    let near = |left: u16, right: u16| left.abs_diff(right) <= 32;
    let pack = |x: u16, y: u16| u32::from(x) | (u32::from(y) << 16);

    if a_y == b_y && b_x == d_x && a_x != b_x && near(a_y, d_y) && (c_x != a_x || c_y != d_y) {
        words[5] = pack(a_x, d_y);
        return true;
    }
    if a_x == c_x && b_x == d_x && a_x != b_x && c_y == d_y && near(a_y, c_y) && b_y != a_y {
        words[3] = pack(b_x, a_y);
        return true;
    }
    if a_x == c_x && b_x == d_x && a_x != b_x && c_y == d_y && near(b_y, c_y) && a_y != b_y {
        words[1] = pack(a_x, b_y);
        return true;
    }
    if a_y == b_y && a_x == c_x && a_x != b_x && near(a_y, c_y) && (d_x != b_x || d_y != c_y) {
        words[7] = pack(b_x, c_y);
        return true;
    }

    false
}

fn gp0_command_is_corrupt_br2_character_model_draw(words: &[u32]) -> bool {
    gp0_command_is_corrupt_br2_character_model_draw_for_packet(0, words)
}

fn gp0_command_is_corrupt_br2_character_model_draw_for_packet(
    packet_address: u32,
    words: &[u32],
) -> bool {
    let Some(command) = words.first() else {
        return false;
    };
    let opcode = (command >> 24) as u8;
    if !matches!(opcode, 0x24..=0x27 | 0x2c..=0x2f | 0x34..=0x37 | 0x3c..=0x3f) {
        return false;
    }
    let Some(descriptor) = gp0_command_texture_descriptor(words) else {
        return false;
    };
    let alternate_model_descriptor =
        br2_alternate_character_model_descriptor(packet_address, descriptor);
    if !br2_character_model_texture(descriptor) && !alternate_model_descriptor {
        return false;
    }

    let bounds = gp0_command_draw_bounds(words);
    if alternate_model_descriptor
        && !bounds.is_some_and(br2_alternate_character_model_bounds_are_coherent)
    {
        return true;
    }

    let vertices = gp0_command_vertex_words(words)
        .unwrap_or_default()
        .into_iter()
        .map(gp0_signed_xy)
        .collect::<Vec<_>>();
    gp0_br2_character_model_vertices_have_compact_outlier(&vertices)
}

#[cfg(test)]
fn gp0_br2_character_model_pointer_contamination_is_uv_padding_only(words: &[u32]) -> bool {
    gp0_br2_character_model_pointer_contamination_is_uv_padding_only_for_packet(0, words)
}

fn gp0_br2_character_model_pointer_contamination_is_uv_padding_only_for_packet(
    packet_address: u32,
    words: &[u32],
) -> bool {
    if !gp0_command_is_br2_character_model_for_packet(packet_address, words) {
        return false;
    }
    gp0_textured_polygon_pointer_contamination_is_uv_padding_only(words)
}

fn gp0_textured_polygon_pointer_contamination_is_uv_padding_only(words: &[u32]) -> bool {
    // In textured polygons only the first UV word carries CLUT and the second
    // carries TPage. The upper half of later UV words is ignored by the GPU,
    // and BR2 leaves stale 0x803x values there. Do not treat those padding
    // halves as RAM pointers, while still rejecting pointer-shaped vertices or
    // descriptor words.
    let ignored_uv_padding_indices: &[usize] = match (words[0] >> 24) as u8 {
        0x24..=0x27 => &[6],
        0x2c..=0x2f => &[6, 8],
        0x34..=0x37 => &[8],
        0x3c..=0x3f => &[8, 11],
        _ => return false,
    };
    let mut saw_pointer_padding = false;
    for (index, word) in words.iter().copied().enumerate().skip(1) {
        if !looks_like_mapped_ram_pointer_word(word) {
            continue;
        }
        if !ignored_uv_padding_indices.contains(&index) {
            return false;
        }
        saw_pointer_padding = true;
    }
    saw_pointer_padding
}

fn gp0_command_is_br2_current_otc_model_atlas_strip_false_positive_for_packet(
    packet_address: u32,
    words: &[u32],
    bounds: Gp0DrawBounds,
) -> bool {
    let packet_address = packet_address & 0x00ff_fffc;
    if !(BR2_CHARACTER_MODEL_PACKET_START..BR2_CHARACTER_MODEL_PACKET_END).contains(&packet_address)
    {
        return false;
    }
    if words.len() != 9 || !matches!((words[0] >> 24) as u8, 0x2c..=0x2f) {
        return false;
    }
    if gp0_command_texture_descriptor(words) != Some((BR2_CHARACTER_MODEL_TEXTURE_PAGE, 0x799a)) {
        return false;
    }
    if bounds.command_like_texture_words < 3
        || bounds.width() < 160
        || bounds.height() > 96
        || bounds.width() < bounds.height().saturating_mul(2)
    {
        return false;
    }
    if bounds.primitive_pointer_words > 0
        && !gp0_br2_character_model_pointer_contamination_is_uv_padding_only_for_packet(
            packet_address,
            words,
        )
    {
        return false;
    }

    let texture_coordinates = gp0_command_texture_words(words)
        .unwrap_or_default()
        .into_iter()
        .map(|word| ((word & 0x00ff) as i32, ((word >> 8) & 0x00ff) as i32))
        .collect::<Vec<_>>();
    if texture_coordinates.len() != 4 {
        return false;
    }
    let min_u = texture_coordinates
        .iter()
        .map(|(u, _)| *u)
        .min()
        .unwrap_or_default();
    let max_u = texture_coordinates
        .iter()
        .map(|(u, _)| *u)
        .max()
        .unwrap_or_default();
    let min_v = texture_coordinates
        .iter()
        .map(|(_, v)| *v)
        .min()
        .unwrap_or_default();
    let max_v = texture_coordinates
        .iter()
        .map(|(_, v)| *v)
        .max()
        .unwrap_or_default();

    (0xc0..=0xdf).contains(&min_u)
        && (0xc0..=0xdf).contains(&max_u)
        && (0xd0..=0xdf).contains(&min_v)
        && (0xd0..=0xdf).contains(&max_v)
}

fn gp0_br2_character_model_vertices_have_compact_outlier(vertices: &[(i32, i32)]) -> bool {
    if !(3..=4).contains(&vertices.len()) {
        return false;
    }
    let min_outlier_distance = if vertices.len() == 3 { 96 } else { 64 };
    for outlier_index in 0..vertices.len() {
        let clustered = vertices
            .iter()
            .enumerate()
            .filter_map(|(index, vertex)| (index != outlier_index).then_some(vertex))
            .collect::<Vec<_>>();
        let cluster_diameter = clustered
            .iter()
            .enumerate()
            .flat_map(|(index, left)| {
                clustered[index + 1..]
                    .iter()
                    .map(move |right| left.0.abs_diff(right.0).max(left.1.abs_diff(right.1)))
            })
            .max()
            .unwrap_or(0);
        if cluster_diameter > 24 {
            continue;
        }

        let outlier = &vertices[outlier_index];
        let distance_to_cluster = clustered
            .iter()
            .map(|vertex| {
                outlier
                    .0
                    .abs_diff(vertex.0)
                    .max(outlier.1.abs_diff(vertex.1))
            })
            .min()
            .unwrap_or(0);
        if distance_to_cluster >= min_outlier_distance {
            return true;
        }
    }
    false
}

fn gp0_br2_character_model_compact_outlier_is_clipped_edge_fragment(
    words: &[u32],
    bounds: Gp0DrawBounds,
) -> bool {
    let opcode = words.first().map(|word| (word >> 24) as u8);
    let triangle = opcode.is_some_and(|opcode| matches!(opcode, 0x24..=0x27 | 0x34..=0x37));
    let thin_fragment = bounds.width() <= 48 || bounds.height() <= 48;
    let touches_display_edge =
        bounds.min_x <= 0 || bounds.max_x >= 639 || bounds.min_y <= 0 || bounds.max_y >= 479;

    triangle && thin_fragment && touches_display_edge
}

fn gp0_replay_safe_draw_command_ranges_with_policy(
    words: &[u32],
    allow_current_otc_atlas_draws: bool,
) -> Vec<std::ops::Range<usize>> {
    gp0_replay_safe_draw_command_ranges_with_policy_and_state(
        words,
        allow_current_otc_atlas_draws,
        (0, 0),
    )
}

fn gp0_replay_safe_draw_command_ranges_with_policy_and_state(
    words: &[u32],
    allow_current_otc_atlas_draws: bool,
    initial_drawing_offset: (i32, i32),
) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut offset = 0;
    let mut pending_state_start = None;
    let mut pending_texture_page = None;
    let mut drawing_offset = initial_drawing_offset;
    while offset < words.len() {
        let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
            break;
        };
        if command_words == 0 || offset + command_words > words.len() {
            break;
        }
        let end = offset + command_words;

        if gp0_command_is_replay_safe_state(&words[offset..end]) {
            pending_state_start.get_or_insert(offset);
            if let Some(texture_page) = gp0_replay_state_texture_page(&words[offset..end]) {
                pending_texture_page = Some(texture_page);
            }
            if words[offset] >> 24 == 0xe5 {
                drawing_offset = gp0_drawing_offset_xy(words[offset]);
            }
            offset = end;
            continue;
        }

        let reject_reason = gp0_command_replay_draw_reject_reason_with_state(
            &words[offset..end],
            pending_texture_page,
            drawing_offset,
        );
        let current_otc_atlas_draw = allow_current_otc_atlas_draws
            && matches!(
                reject_reason,
                Some(
                    Gp0ReplayDrawRejectReason::LinkedListArtifact
                        | Gp0ReplayDrawRejectReason::Br2StageTransitionAtlas
                )
            )
            && gp0_command_draw_bounds_with_offset(&words[offset..end], drawing_offset)
                .is_some_and(|bounds| {
                    bounds.width() <= 640 && bounds.height() <= 480 && bounds.area() <= 307_200
                });
        let current_otc_title_quadrant = allow_current_otc_atlas_draws
            && gp0_command_is_br2_title_quadrant_rect(&words[offset..end]);
        let current_otc_stage_draw = allow_current_otc_atlas_draws
            && gp0_command_texture_descriptor(&words[offset..end]).is_some_and(
                |(texture_page, clut)| {
                    br2_reused_texture_page_matches(texture_page, BR2_CHARACTER_MODEL_TEXTURE_PAGE)
                        && BR2_STAGE_TEXTURE_CLUTS.contains(&clut)
                },
            )
            && matches!(
                reject_reason,
                Some(
                    Gp0ReplayDrawRejectReason::CommandTextureContamination
                        | Gp0ReplayDrawRejectReason::PrimitivePointerContamination
                        | Gp0ReplayDrawRejectReason::TitleOverlayAtlas
                        | Gp0ReplayDrawRejectReason::Br2StageTransitionAtlas
                )
            );
        if reject_reason.is_none()
            || current_otc_atlas_draw
            || current_otc_title_quadrant
            || current_otc_stage_draw
        {
            let start = pending_state_start.take().unwrap_or(offset);
            ranges.push(start..end);
        } else {
            pending_state_start = None;
            pending_texture_page = None;
        }
        offset = end;
    }
    ranges
}

fn gp0_replay_safe_state_command_ranges(words: &[u32]) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut offset = 0;
    while offset < words.len() {
        let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
            break;
        };
        if command_words == 0 || offset + command_words > words.len() {
            break;
        }
        let end = offset + command_words;
        if gp0_command_is_replay_safe_state(&words[offset..end]) {
            ranges.push(offset..end);
        }
        offset = end;
    }
    ranges
}

fn gp0_command_is_replay_safe_state(words: &[u32]) -> bool {
    if words.len() != 1 {
        return false;
    }

    let command = words[0];
    match command >> 24 {
        0xe1 | 0xe2 | 0xe3 | 0xe4 | 0xe6 => true,
        0xe5 => {
            let (x, y) = gp0_drawing_offset_xy(command);
            (-512..=512).contains(&x) && (-512..=512).contains(&y)
        }
        _ => false,
    }
}

fn gp0_command_vertex_words(words: &[u32]) -> Option<Vec<u32>> {
    let opcode = (*words.first()? >> 24) as u8;
    let vertices = match opcode {
        0x20..=0x23 if words.len() >= 4 => vec![words[1], words[2], words[3]],
        0x24..=0x27 if words.len() >= 7 => vec![words[1], words[3], words[5]],
        0x28..=0x2b if words.len() >= 5 => vec![words[1], words[2], words[3], words[4]],
        0x2c..=0x2f if words.len() >= 9 => vec![words[1], words[3], words[5], words[7]],
        0x30..=0x33 if words.len() >= 6 => vec![words[1], words[3], words[5]],
        0x34..=0x37 if words.len() >= 9 => vec![words[1], words[4], words[7]],
        0x38..=0x3b if words.len() >= 8 => vec![words[1], words[3], words[5], words[7]],
        0x3c..=0x3f if words.len() >= 12 => vec![words[1], words[4], words[7], words[10]],
        0x40..=0x47 if words.len() >= 3 => vec![words[1], words[2]],
        0x48..=0x4f => gp0_command_polyline_vertex_words(words, false),
        0x50..=0x57 if words.len() >= 4 => vec![words[1], words[3]],
        0x58..=0x5f => gp0_command_polyline_vertex_words(words, true),
        0x60..=0x7f if words.len() >= 2 => vec![words[1]],
        _ => Vec::new(),
    };
    Some(vertices)
}

fn gp0_command_polyline_vertex_words(words: &[u32], shaded: bool) -> Vec<u32> {
    let mut vertices = Vec::new();
    let mut offset = 1usize;
    while let Some(word) = words.get(offset).copied() {
        if gp0_command_polyline_terminator(word) {
            break;
        }
        vertices.push(word);
        offset = offset.saturating_add(if shaded { 2 } else { 1 });
    }
    vertices
}

fn gp0_command_polyline_terminator(word: u32) -> bool {
    word & 0xf000_f000 == 0x5000_5000
}

fn gp0_command_texture_words(words: &[u32]) -> Option<Vec<u32>> {
    let opcode = (*words.first()? >> 24) as u8;
    let texture_words = match opcode {
        0x24..=0x27 if words.len() >= 7 => vec![words[2], words[4], words[6]],
        0x2c..=0x2f if words.len() >= 9 => vec![words[2], words[4], words[6], words[8]],
        0x34..=0x37 if words.len() >= 9 => vec![words[2], words[5], words[8]],
        0x3c..=0x3f if words.len() >= 12 => {
            vec![words[2], words[5], words[8], words[11]]
        }
        _ => Vec::new(),
    };
    Some(texture_words)
}

fn gp0_command_texture_descriptor(words: &[u32]) -> Option<(u16, u16)> {
    let texture_words = gp0_command_texture_words(words)?;
    if texture_words.len() < 2 {
        return None;
    }

    let clut = (texture_words[0] >> 16) as u16;
    let texture_page = (texture_words[1] >> 16) as u16;
    Some((texture_page, clut))
}

#[cfg(test)]
fn gp0_command_is_br2_status_glyph_tile(words: &[u32]) -> bool {
    gp0_command_is_br2_status_glyph_tile_with_drawing_offset(words, (0, 0))
}

fn gp0_command_is_br2_status_glyph_tile_with_drawing_offset(
    words: &[u32],
    drawing_offset: (i32, i32),
) -> bool {
    let Some((texture_page, clut)) = gp0_command_texture_descriptor(words) else {
        return false;
    };
    if !br2_reused_texture_page_matches(texture_page, 0x002f)
        || (clut & 0x003f) != 0x001f
        || !matches!(gp0_clut_row(clut), 483 | 484)
    {
        return false;
    }
    let Some(raw_bounds) = gp0_command_draw_bounds(words) else {
        return false;
    };
    let Some(visible_bounds) = gp0_command_draw_bounds_with_offset(words, drawing_offset) else {
        return false;
    };
    let compact =
        raw_bounds.width() <= 32 && raw_bounds.height() <= 32 && raw_bounds.area() <= 1_024;
    let in_hud_band = |bounds: Gp0DrawBounds| bounds.max_y <= 96 || bounds.min_y >= 384;

    compact && (in_hud_band(raw_bounds) || in_hud_band(visible_bounds))
}

fn gp0_command_is_br2_non_gameplay_high_bank_atlas(words: &[u32]) -> bool {
    let Some((texture_page, clut)) = gp0_command_texture_descriptor(words) else {
        return false;
    };
    if texture_page != 0x002f || (clut & 0x003f) != 0x001f {
        return false;
    }

    // Rows 483/484 are the live match character/effect aliases documented by
    // the framebuffer sampler. Adjacent rows belong to title, select and HUD
    // atlases and must not be replayed as persistent stage geometry.
    !matches!(gp0_clut_row(clut), 483 | 484)
}

fn gp0_command_is_br2_transient_stage_effect(words: &[u32], drawing_offset: (i32, i32)) -> bool {
    let Some((texture_page, clut)) = gp0_command_texture_descriptor(words) else {
        return false;
    };
    if texture_page & !0x0200 != 0x002f || !matches!(gp0_clut_row(clut), 483 | 484) {
        return false;
    }

    gp0_command_draw_bounds_with_offset(words, drawing_offset).is_some_and(|bounds| {
        bounds.has_visible_x
            && bounds.min_y <= 479
            && bounds.max_y >= 0
            && bounds.width() >= 64
            && bounds.height() >= 32
            && bounds.area() >= 4_096
    })
}

fn words_have_br2_character_model_texture_at(packet_address: u32, words: &[u32]) -> bool {
    let mut offset = 0usize;
    while offset < words.len() {
        let Some(command_words) = gp0_command_word_count(&words[offset..]) else {
            return false;
        };
        if command_words == 0 || offset + command_words > words.len() {
            return false;
        }
        if gp0_command_is_br2_character_model_for_packet(
            packet_address,
            &words[offset..offset + command_words],
        ) {
            return true;
        }
        offset += command_words;
    }
    false
}

fn br2_character_model_texture((texture_page, clut): (u16, u16)) -> bool {
    br2_reused_texture_page_matches(texture_page, BR2_CHARACTER_MODEL_TEXTURE_PAGE)
        && BR2_CHARACTER_MODEL_CLUT_ROWS.contains(&gp0_clut_row(clut))
}

fn br2_beast_character_model_candidate_descriptor((texture_page, clut): (u16, u16)) -> bool {
    matches!(
        (texture_page & !0x0200, clut & 0x003f),
        (0x000e, 0x001e) | (0x001b, 0x001b)
    ) && (480..=490).contains(&gp0_clut_row(clut))
}

fn br2_reused_texture_page_matches(texture_page: u16, expected_page: u16) -> bool {
    texture_page & !0x0200 == expected_page
}

fn gp0_command_is_br2_character_model_for_packet(packet_address: u32, words: &[u32]) -> bool {
    let Some(descriptor) = gp0_command_texture_descriptor(words) else {
        return false;
    };
    br2_character_model_texture(descriptor)
        || br2_low_ram_character_model_texture(packet_address, descriptor, words)
        || br2_high_ram_beast_character_model_texture(packet_address, descriptor, words)
}

#[cfg(test)]
fn gp0_command_is_valid_br2_character_model_draw(words: &[u32]) -> bool {
    gp0_command_is_valid_br2_character_model_draw_for_packet(0, words)
}

fn gp0_command_is_valid_br2_character_model_draw_for_packet(
    packet_address: u32,
    words: &[u32],
) -> bool {
    if !gp0_command_is_br2_character_model_for_packet(packet_address, words)
        || gp0_command_is_corrupt_br2_character_model_draw_for_packet(packet_address, words)
    {
        return false;
    }
    gp0_command_draw_bounds(words).is_some_and(|bounds| {
        bounds.width() > 1
            && bounds.height() > 1
            && bounds.width() <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_WIDTH
            && bounds.height() <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_HEIGHT
            && bounds.has_visible_x
            && bounds.min_x <= 639
            && bounds.max_x >= 0
            && bounds.min_y <= 479
            && bounds.max_y >= 0
    })
}

#[cfg(test)]
fn gp0_current_otc_br2_character_model_draw_bounds_for_packet(
    packet_address: u32,
    words: &[u32],
    drawing_offset: (i32, i32),
) -> Option<Gp0DrawBounds> {
    gp0_current_otc_br2_character_model_draw_evaluation_for_packet(
        packet_address,
        words,
        drawing_offset,
    )
    .ok()
}

fn gp0_current_otc_br2_character_model_draw_evaluation_for_packet(
    packet_address: u32,
    words: &[u32],
    drawing_offset: (i32, i32),
) -> Result<Gp0DrawBounds, Gp0ReplayDrawRejectReason> {
    let descriptor =
        gp0_command_texture_descriptor(words).ok_or(Gp0ReplayDrawRejectReason::ModelPrefilter)?;
    let high_ram_beast_model =
        br2_high_ram_beast_character_model_descriptor(packet_address, descriptor);
    if !br2_character_model_texture(descriptor)
        && !br2_alternate_character_model_descriptor(packet_address, descriptor)
    {
        return Err(Gp0ReplayDrawRejectReason::ModelPrefilter);
    }
    if high_ram_beast_model
        && let Some(reason) =
            gp0_command_replay_draw_reject_reason_with_state(words, None, drawing_offset)
        && matches!(
            reason,
            Gp0ReplayDrawRejectReason::LinkedListArtifact
                | Gp0ReplayDrawRejectReason::TitleOverlayAtlas
                | Gp0ReplayDrawRejectReason::Br2StageTransitionAtlas
                | Gp0ReplayDrawRejectReason::KnownRecoveryAtlas
        )
    {
        return Err(reason);
    }
    if gp0_command_sequence_has_known_recovery_atlas_corruption(words) {
        return Err(Gp0ReplayDrawRejectReason::KnownRecoveryAtlas);
    }
    if gp0_command_is_linked_list_dma_blocking_artifact(words) {
        return Err(Gp0ReplayDrawRejectReason::LinkedListArtifact);
    }
    if gp0_command_is_unsafe_br2_785a_recovery_draw(words, drawing_offset) {
        return Err(Gp0ReplayDrawRejectReason::UnsafeBr2785a);
    }

    let high_ram_current_model = (BR2_CHARACTER_MODEL_PACKET_START..BR2_CHARACTER_MODEL_PACKET_END)
        .contains(&(packet_address & 0x00ff_fffc));
    let alternate_current_model =
        br2_alternate_character_model_descriptor(packet_address, descriptor);
    if gp0_command_is_corrupt_br2_character_model_draw_for_packet(packet_address, words) {
        let bounds = gp0_command_draw_bounds(words);
        let clipped_edge_fragment = high_ram_current_model
            && bounds.is_some_and(|bounds| {
                gp0_br2_character_model_compact_outlier_is_clipped_edge_fragment(words, bounds)
            });
        if !alternate_current_model && !clipped_edge_fragment {
            return Err(Gp0ReplayDrawRejectReason::CorruptBr2CharacterModel);
        }
    }
    if words
        .iter()
        .skip(1)
        .any(|word| looks_like_mapped_ram_pointer_word(*word))
        && !gp0_br2_character_model_pointer_contamination_is_uv_padding_only_for_packet(
            packet_address,
            words,
        )
    {
        return Err(Gp0ReplayDrawRejectReason::PrimitivePointerContamination);
    }

    let bounds = gp0_command_draw_bounds_with_offset(words, drawing_offset)
        .ok_or(Gp0ReplayDrawRejectReason::NoBounds)?;
    if bounds.width() <= 1
        || bounds.height() <= 1
        || bounds.width() > BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_WIDTH
        || bounds.height() > BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_HEIGHT
        || bounds.zero_vertices > 1
    {
        return Err(Gp0ReplayDrawRejectReason::UnsafeBounds);
    }
    let non_playfield_bounds = if high_ram_beast_model {
        !br2_alternate_character_model_bounds_are_coherent(bounds)
    } else {
        !bounds.has_visible_x
            || bounds.min_x > 639
            || bounds.max_x < -64
            || bounds.min_y > 423
            || bounds.max_y < 64
    };
    if non_playfield_bounds {
        return Err(Gp0ReplayDrawRejectReason::NonPlayfieldBounds);
    }
    if gp0_command_is_br2_current_otc_model_atlas_strip_false_positive_for_packet(
        packet_address,
        words,
        bounds,
    ) {
        return Err(Gp0ReplayDrawRejectReason::KnownRecoveryAtlas);
    }
    Ok(bounds)
}

fn gp0_command_vertex_word_indices(words: &[u32]) -> Option<&'static [usize]> {
    let opcode = (*words.first()? >> 24) as u8;
    let indices: &'static [usize] = match opcode {
        0x20..=0x23 => &[1, 2, 3],
        0x24..=0x27 => &[1, 3, 5],
        0x28..=0x2b => &[1, 2, 3, 4],
        0x2c..=0x2f => &[1, 3, 5, 7],
        0x30..=0x33 => &[1, 3, 5],
        0x34..=0x37 => &[1, 4, 7],
        0x38..=0x3b => &[1, 3, 5, 7],
        0x3c..=0x3f => &[1, 4, 7, 10],
        0x40..=0x47 => &[1, 2],
        0x50..=0x57 => &[1, 3],
        0x60..=0x7f => &[1],
        _ => return None,
    };
    indices
        .iter()
        .all(|index| *index < words.len())
        .then_some(indices)
}

fn br2_character_model_command_pose_generation(
    words: &[u32],
    word_freshness: &[Option<u64>],
) -> Option<u64> {
    if words.len() != word_freshness.len() {
        return None;
    }

    let vertex_indices = gp0_command_vertex_word_indices(words)?;
    let mut oldest = u64::MAX;
    let mut newest = 0u64;
    for index in vertex_indices {
        let freshness = word_freshness.get(*index).copied().flatten()?;
        oldest = oldest.min(freshness);
        newest = newest.max(freshness);
    }

    // BR2 updates polygon vertices every pose while intentionally reusing the
    // opcode, CLUT, texture page, and UV words for many frames. Only the vertex
    // coordinates define pose freshness; mixing vertex generations still
    // indicates a partially overwritten model packet.
    (newest.saturating_sub(oldest) <= BR2_CHARACTER_MODEL_RECOVERY_BODY_FRESHNESS_SLACK)
        .then_some(newest)
}

fn gp0_command_is_degenerate_br2_character_model_draw_for_packet(
    packet_address: u32,
    words: &[u32],
) -> bool {
    gp0_command_is_br2_character_model_for_packet(packet_address, words)
        && gp0_command_draw_bounds(words)
            .is_some_and(|bounds| bounds.width() <= 1 || bounds.height() <= 1)
}

fn gp0_command_invalid_br2_character_model_blocks_fallback(words: &[u32]) -> bool {
    gp0_command_draw_bounds(words)
        .is_some_and(|bounds| bounds.has_visible_x && bounds.min_y <= 479 && bounds.max_y >= 0)
}

fn br2_character_model_recovery_chain_is_spatially_coherent(
    chain: &[u32],
    packets: &HashMap<u32, Br2CharacterModelRecoveryPacket>,
) -> bool {
    let mut min_x = i32::MAX;
    let mut max_x = i32::MIN;
    let mut min_y = i32::MAX;
    let mut max_y = i32::MIN;
    let mut model_draws = 0usize;

    for address in chain {
        let Some(packet) = packets.get(address) else {
            return false;
        };
        let mut offset = 0usize;
        while offset < packet.words.len() {
            let Some(command_words) = gp0_command_word_count(&packet.words[offset..]) else {
                return false;
            };
            if command_words == 0 || offset + command_words > packet.words.len() {
                return false;
            }
            let command = &packet.words[offset..offset + command_words];
            if gp0_command_is_valid_br2_character_model_draw_for_packet(*address, command) {
                let Some(bounds) = gp0_command_draw_bounds(command) else {
                    return false;
                };
                min_x = min_x.min(bounds.min_x);
                max_x = max_x.max(bounds.max_x);
                min_y = min_y.min(bounds.min_y);
                max_y = max_y.max(bounds.max_y);
                model_draws = model_draws.saturating_add(1);
            }
            offset += command_words;
        }
    }

    if model_draws == 0 {
        return false;
    }
    let width = max_x.saturating_sub(min_x).saturating_add(1);
    let height = max_y.saturating_sub(min_y).saturating_add(1);
    width <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_WIDTH
        && height <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_HEIGHT
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct Gp0DrawBounds {
    min_x: i32,
    max_x: i32,
    min_y: i32,
    max_y: i32,
    has_visible_x: bool,
    zero_vertices: usize,
    zero_texture_words: usize,
    command_like_texture_words: usize,
    primitive_pointer_words: usize,
}

impl Gp0DrawBounds {
    fn with_offset(mut self, drawing_offset: (i32, i32)) -> Self {
        self.min_x = self.min_x.saturating_add(drawing_offset.0);
        self.max_x = self.max_x.saturating_add(drawing_offset.0);
        self.min_y = self.min_y.saturating_add(drawing_offset.1);
        self.max_y = self.max_y.saturating_add(drawing_offset.1);
        self.has_visible_x = self.min_x <= 576 && self.max_x >= -64;
        self
    }

    fn width(self) -> i32 {
        self.max_x.saturating_sub(self.min_x).saturating_add(1)
    }

    fn height(self) -> i32 {
        self.max_y.saturating_sub(self.min_y).saturating_add(1)
    }

    fn area(self) -> i32 {
        self.width().saturating_mul(self.height())
    }

    fn json(self) -> String {
        format!(
            "{{\"min_x\":{},\"max_x\":{},\"min_y\":{},\"max_y\":{},\"width\":{},\"height\":{},\"area\":{},\"has_visible_x\":{},\"zero_vertices\":{},\"zero_texture_words\":{},\"command_like_texture_words\":{},\"primitive_pointer_words\":{}}}",
            self.min_x,
            self.max_x,
            self.min_y,
            self.max_y,
            self.width(),
            self.height(),
            self.area(),
            self.has_visible_x,
            self.zero_vertices,
            self.zero_texture_words,
            self.command_like_texture_words,
            self.primitive_pointer_words
        )
    }
}

fn gp0_draw_bounds_union(left: Gp0DrawBounds, right: Gp0DrawBounds) -> Gp0DrawBounds {
    Gp0DrawBounds {
        min_x: left.min_x.min(right.min_x),
        max_x: left.max_x.max(right.max_x),
        min_y: left.min_y.min(right.min_y),
        max_y: left.max_y.max(right.max_y),
        has_visible_x: left.has_visible_x || right.has_visible_x,
        zero_vertices: left.zero_vertices.saturating_add(right.zero_vertices),
        zero_texture_words: left
            .zero_texture_words
            .saturating_add(right.zero_texture_words),
        command_like_texture_words: left
            .command_like_texture_words
            .saturating_add(right.command_like_texture_words),
        primitive_pointer_words: left
            .primitive_pointer_words
            .saturating_add(right.primitive_pointer_words),
    }
}

fn br2_character_model_generation_bounds_are_coherent(bounds: Gp0DrawBounds) -> bool {
    bounds.width() <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_WIDTH
        && bounds.height() <= BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_HEIGHT
}

fn br2_character_model_distinct_coherent_draw_addresses(
    draws_by_texture: &HashMap<(u16, u16), Vec<(u32, Gp0DrawBounds)>>,
    minimum_distinct_draws: usize,
) -> HashSet<u32> {
    let mut selected = HashSet::new();
    let mut distinct_bounds = HashSet::new();

    for (descriptor, draws) in draws_by_texture {
        let annular_effect_draws =
            br2_character_model_annular_effect_draw_addresses(*descriptor, draws);

        for address_component in br2_character_model_address_components(draws) {
            let address_component = address_component
                .into_iter()
                .filter(|(address, _)| !annular_effect_draws.contains(address))
                .collect::<Vec<_>>();
            if address_component.is_empty() {
                continue;
            }

            for mut spatial_component in br2_character_model_spatial_components(&address_component)
            {
                let bounds = spatial_component
                    .iter()
                    .map(|(_, bounds)| *bounds)
                    .reduce(gp0_draw_bounds_union);
                if !bounds.is_some_and(|bounds| {
                    br2_character_model_spatial_component_is_coherent(
                        *descriptor,
                        &spatial_component,
                        bounds,
                    )
                }) {
                    continue;
                }

                // Identical screen bounds from the same material are retained
                // OTC pose duplicates, not additional fighter components.
                spatial_component.sort_unstable_by_key(|(address, _)| *address);
                spatial_component.reverse();
                for (address, bounds) in spatial_component {
                    let key = (
                        descriptor.0,
                        descriptor.1,
                        bounds.min_x,
                        bounds.max_x,
                        bounds.min_y,
                        bounds.max_y,
                    );
                    if distinct_bounds.insert(key) {
                        selected.insert(address);
                    }
                }
            }
        }
    }

    if selected.len() >= minimum_distinct_draws {
        selected
    } else {
        HashSet::new()
    }
}

fn br2_character_model_rejected_draw_addresses(
    draws_by_texture: &HashMap<(u16, u16), Vec<(u32, Gp0DrawBounds)>>,
    reject_annular_effects: bool,
) -> HashSet<u32> {
    let mut rejected = HashSet::new();
    for (descriptor, draws) in draws_by_texture {
        let annular_effect_draws =
            br2_character_model_annular_effect_draw_addresses(*descriptor, draws);
        if reject_annular_effects {
            rejected.extend(annular_effect_draws.iter().copied());
        }

        // BR2 allocates each fighter's packet run separately, but both fighters
        // reuse the same texture descriptor and can overlap during attacks.
        // Split allocation runs first so screen-space overlap cannot merge two
        // valid models into one oversized component.
        for address_component in br2_character_model_address_components(draws) {
            let address_component = address_component
                .into_iter()
                .filter(|(address, _)| !annular_effect_draws.contains(address))
                .collect::<Vec<_>>();
            if address_component.is_empty() {
                continue;
            }
            for spatial_component in br2_character_model_spatial_components(&address_component) {
                let bounds = spatial_component
                    .iter()
                    .map(|(_, bounds)| *bounds)
                    .reduce(gp0_draw_bounds_union);
                if bounds.is_some_and(|bounds| {
                    !br2_character_model_spatial_component_is_coherent(
                        *descriptor,
                        &spatial_component,
                        bounds,
                    )
                }) {
                    rejected.extend(spatial_component.into_iter().map(|(address, _)| address));
                }
            }
        }
    }
    rejected
}

fn br2_character_model_spatial_component_is_coherent(
    descriptor: (u16, u16),
    draws: &[(u32, Gp0DrawBounds)],
    bounds: Gp0DrawBounds,
) -> bool {
    if br2_character_model_generation_bounds_are_coherent(bounds) {
        return true;
    }

    // Perspective clipping can leave a small low-RAM fighter component with
    // one edge off-screen. The individual polygons remain bounded and share a
    // vertical band, but their union can exceed the normal 320-pixel fighter
    // width. Preserve those two- or three-polygon fragments without allowing
    // the longer select/stage atlas strips that previously covered the frame.
    if !(2..BR2_CHARACTER_MODEL_RECOVERY_MIN_PACKETS).contains(&draws.len())
        || bounds.width() > BR2_CHARACTER_MODEL_RECOVERY_CLIPPED_COMPONENT_MAX_WIDTH
        || bounds.height() > BR2_CHARACTER_MODEL_RECOVERY_MAX_CHAIN_HEIGHT
        || bounds.area() > BR2_CHARACTER_MODEL_RECOVERY_CLIPPED_COMPONENT_MAX_AREA
        || !draws.iter().all(|(address, draw)| {
            br2_low_ram_character_model_descriptor(*address, descriptor)
                && br2_character_model_generation_bounds_are_coherent(*draw)
        })
    {
        return false;
    }

    let highest_top = draws
        .iter()
        .map(|(_, draw)| draw.min_y)
        .max()
        .unwrap_or(i32::MAX);
    let lowest_bottom = draws
        .iter()
        .map(|(_, draw)| draw.max_y)
        .min()
        .unwrap_or(i32::MIN);
    highest_top <= lowest_bottom.saturating_add(BR2_CHARACTER_MODEL_RECOVERY_COMPONENT_GAP)
}

fn br2_character_model_annular_effect_draw_addresses(
    descriptor: (u16, u16),
    draws: &[(u32, Gp0DrawBounds)],
) -> HashSet<u32> {
    br2_character_model_annular_effect_draw_groups(descriptor, draws)
        .into_iter()
        .flatten()
        .map(|(address, _)| address)
        .collect()
}

fn br2_character_model_annular_effect_draw_groups(
    descriptor: (u16, u16),
    draws: &[(u32, Gp0DrawBounds)],
) -> Vec<Vec<(u32, Gp0DrawBounds)>> {
    let components = br2_character_model_address_components(draws);
    let primary_components = components
        .iter()
        .filter(|component| br2_character_model_draw_group_is_annular_effect(descriptor, component))
        .cloned()
        .collect::<Vec<_>>();
    if primary_components.is_empty() {
        return Vec::new();
    }

    let standard_beast_ring =
        br2_reused_texture_page_matches(descriptor.0, BR2_CHARACTER_MODEL_TEXTURE_PAGE)
            && descriptor.1 == 0x799a;
    if !standard_beast_ring {
        return primary_components;
    }

    let primary_bounds = primary_components
        .iter()
        .map(|component| {
            component
                .iter()
                .map(|(_, bounds)| *bounds)
                .reduce(gp0_draw_bounds_union)
                .expect("annular primary component must have bounds")
        })
        .collect::<Vec<_>>();
    let mut groups = primary_components.clone();

    for component in components {
        if br2_character_model_draw_group_is_annular_effect(descriptor, &component)
            || component.is_empty()
            || component.len() > BR2_CHARACTER_MODEL_ANNULAR_CONTINUATION_MAX_DRAWS
            || component.iter().any(|(_, bounds)| {
                bounds.width() < BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MIN_DRAW_WIDTH
            })
        {
            continue;
        }
        let Some(bounds) = component
            .iter()
            .map(|(_, bounds)| *bounds)
            .reduce(gp0_draw_bounds_union)
        else {
            continue;
        };
        if bounds.height() > BR2_CHARACTER_MODEL_ANNULAR_CONTINUATION_MAX_HEIGHT {
            continue;
        }
        let Some(primary_index) = primary_bounds
            .iter()
            .enumerate()
            .filter(|(_, primary)| gp0_draw_bounds_overlap(**primary, bounds))
            .min_by_key(|(_, primary)| gp0_draw_bounds_center_distance(**primary, bounds))
            .map(|(index, _)| index)
        else {
            continue;
        };
        groups[primary_index].extend(component);
    }

    groups
}

fn gp0_draw_bounds_overlap(left: Gp0DrawBounds, right: Gp0DrawBounds) -> bool {
    left.min_x <= right.max_x
        && right.min_x <= left.max_x
        && left.min_y <= right.max_y
        && right.min_y <= left.max_y
}

fn gp0_draw_bounds_center_distance(left: Gp0DrawBounds, right: Gp0DrawBounds) -> i32 {
    left.min_x
        .saturating_add(left.max_x)
        .saturating_sub(right.min_x.saturating_add(right.max_x))
        .abs()
        .saturating_add(
            left.min_y
                .saturating_add(left.max_y)
                .saturating_sub(right.min_y.saturating_add(right.max_y))
                .abs(),
        )
}

fn br2_character_model_address_components(
    draws: &[(u32, Gp0DrawBounds)],
) -> Vec<Vec<(u32, Gp0DrawBounds)>> {
    let mut sorted = draws.to_vec();
    sorted.sort_unstable_by_key(|(address, _)| *address);

    let mut components = Vec::<Vec<(u32, Gp0DrawBounds)>>::new();
    let mut previous_address = None::<u32>;
    for draw in sorted {
        let starts_new_component = previous_address.is_some_and(|previous| {
            draw.0.saturating_sub(previous) > BR2_CHARACTER_MODEL_RECOVERY_ADDRESS_COMPONENT_GAP
        });
        if starts_new_component || components.is_empty() {
            components.push(Vec::new());
        }
        previous_address = Some(draw.0);
        components
            .last_mut()
            .expect("character model address component must exist")
            .push(draw);
    }
    components
}

fn br2_character_model_spatial_components(
    draws: &[(u32, Gp0DrawBounds)],
) -> Vec<Vec<(u32, Gp0DrawBounds)>> {
    let mut sorted = draws.to_vec();
    sorted.sort_unstable_by_key(|(address, bounds)| (bounds.min_x, bounds.max_x, *address));

    let mut components = Vec::<Vec<(u32, Gp0DrawBounds)>>::new();
    let mut component_max_x = i32::MIN;
    for draw in sorted {
        let starts_new_component = components.last().is_some()
            && draw.1.min_x
                > component_max_x.saturating_add(BR2_CHARACTER_MODEL_RECOVERY_COMPONENT_GAP);
        if starts_new_component {
            components.push(Vec::new());
            component_max_x = i32::MIN;
        } else if components.is_empty() {
            components.push(Vec::new());
        }
        component_max_x = component_max_x.max(draw.1.max_x);
        components
            .last_mut()
            .expect("character model component must exist")
            .push(draw);
    }
    components
}

fn br2_character_model_draw_group_is_annular_effect(
    descriptor: (u16, u16),
    draws: &[(u32, Gp0DrawBounds)],
) -> bool {
    let standard_beast_ring =
        br2_reused_texture_page_matches(descriptor.0, BR2_CHARACTER_MODEL_TEXTURE_PAGE)
            && descriptor.1 == 0x799a;
    let alternate_beast_ring = br2_beast_character_model_candidate_descriptor(descriptor);
    if !standard_beast_ring && !alternate_beast_ring {
        return false;
    }
    // The captured one-shot Beast fragment is one oversized polygon whose
    // vertices extend well outside the visible playfield. Wide clipped fighter
    // limbs can have similar dimensions, so size alone must not classify a
    // normal overlapping fighter allocation as a transient ring.
    if draws.len() == 1
        && draws.iter().any(|(_, bounds)| {
            bounds.width() >= 240
                && bounds.height() >= 80
                && bounds.area() >= 20_000
                && (bounds.min_x < -128
                    || bounds.max_x > 640
                    || bounds.min_y < -128
                    || bounds.max_y > 608)
        })
    {
        return true;
    }
    let Some(bounds) = draws
        .iter()
        .map(|(_, bounds)| *bounds)
        .reduce(gp0_draw_bounds_union)
    else {
        return false;
    };
    // P2 Beast can emit a clipped horizontal ring as six adjacent wide
    // polygons. The allocation is split before the remaining two polygons by
    // a large RAM gap, so the normal ten-draw annular threshold cannot see the
    // complete effect. Require the captured off-screen-to-off-screen geometry
    // and uniformly wide strips so compact fighter limbs remain model draws.
    let clipped_wide_band = standard_beast_ring
        && (BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MIN_DRAWS
            ..=BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MAX_DRAWS)
            .contains(&draws.len())
        && bounds.width() >= BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MIN_WIDTH
        && bounds.height() >= BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MIN_HEIGHT
        && bounds.min_x <= -256
        && bounds.max_x >= 480
        && draws
            .iter()
            .all(|(_, draw)| draw.width() >= BR2_CHARACTER_MODEL_WIDE_BAND_EFFECT_MIN_DRAW_WIDTH);
    if clipped_wide_band {
        return true;
    }
    if draws.len() < BR2_CHARACTER_MODEL_ANNULAR_EFFECT_MIN_DRAWS {
        return false;
    }
    if bounds.width() < BR2_CHARACTER_MODEL_ANNULAR_EFFECT_MIN_WIDTH
        || bounds.height() < BR2_CHARACTER_MODEL_ANNULAR_EFFECT_MIN_HEIGHT
    {
        return false;
    }

    let center_x2 = bounds.min_x.saturating_add(bounds.max_x);
    let center_y2 = bounds.min_y.saturating_add(bounds.max_y);
    let mut central_draws = 0usize;
    let mut quadrants = [false; 4];
    for (_, draw) in draws {
        let draw_center_x2 = draw.min_x.saturating_add(draw.max_x);
        let draw_center_y2 = draw.min_y.saturating_add(draw.max_y);
        let dx2 = draw_center_x2.saturating_sub(center_x2);
        let dy2 = draw_center_y2.saturating_sub(center_y2);
        if dx2.abs().saturating_mul(2) <= bounds.width()
            && dy2.abs().saturating_mul(2) <= bounds.height()
        {
            central_draws = central_draws.saturating_add(1);
        }
        let quadrant = match (dx2 < 0, dy2 < 0) {
            (true, true) => 0,
            (false, true) => 1,
            (true, false) => 2,
            (false, false) => 3,
        };
        quadrants[quadrant] = true;
    }

    central_draws <= (draws.len() / 8).max(1) && quadrants.into_iter().all(|occupied| occupied)
}

fn br2_recovery_stage_model_alias_descriptor(
    (texture_page, clut): (u16, u16),
) -> Option<(u16, u16)> {
    let normalized_page = texture_page & !(0x0200 | 0x0060);
    let normalized_model_page = BR2_CHARACTER_MODEL_TEXTURE_PAGE & !(0x0200 | 0x0060);
    (clut == 0x7959 && normalized_page == normalized_model_page)
        .then_some((normalized_model_page, clut))
}

fn br2_recovery_stage_model_alias_draw_is_oversized(bounds: Gp0DrawBounds) -> bool {
    bounds.width() >= BR2_RECOVERY_STAGE_MODEL_ALIAS_MIN_DRAW_WIDTH
        && bounds.height() >= BR2_RECOVERY_STAGE_MODEL_ALIAS_MIN_DRAW_HEIGHT
        && bounds.area() >= BR2_RECOVERY_STAGE_MODEL_ALIAS_MIN_DRAW_AREA
}

fn gp0_command_draw_bounds(words: &[u32]) -> Option<Gp0DrawBounds> {
    gp0_command_draw_bounds_with_offset(words, (0, 0))
}

fn gp0_command_draw_bounds_with_offset(
    words: &[u32],
    drawing_offset: (i32, i32),
) -> Option<Gp0DrawBounds> {
    let opcode = (*words.first()? >> 24) as u8;
    let points = gp0_command_vertex_words(words)?;
    if points.is_empty() {
        return None;
    }

    let mut min_x = i32::MAX;
    let mut max_x = i32::MIN;
    let mut min_y = i32::MAX;
    let mut max_y = i32::MIN;
    let mut has_visible_x = false;
    let mut zero_vertices = 0usize;
    let mut record_point = |word| {
        let (x, y) = gp0_signed_xy(word);
        min_x = min_x.min(x);
        max_x = max_x.max(x);
        min_y = min_y.min(y);
        max_y = max_y.max(y);
        has_visible_x |= (-64..=576).contains(&x);
        if x == 0 && y == 0 {
            zero_vertices = zero_vertices.saturating_add(1);
        }
    };

    if (0x60..=0x7f).contains(&opcode) {
        let (x, y) = gp0_signed_xy(points[0]);
        let (width, height) = gp0_command_rect_dimensions(opcode, words)?;
        let max_rect_x = x.saturating_add(width.saturating_sub(1));
        let max_rect_y = y.saturating_add(height.saturating_sub(1));
        record_point(points[0]);
        min_x = min_x.min(max_rect_x);
        max_x = max_x.max(max_rect_x);
        min_y = min_y.min(max_rect_y);
        max_y = max_y.max(max_rect_y);
        has_visible_x |= x <= 576 && max_rect_x >= -64;
    } else {
        for word in points {
            record_point(word);
        }
    }
    let texture_words = gp0_command_texture_words(words)?;
    let zero_texture_words = texture_words.iter().filter(|word| **word == 0).count();
    let command_like_texture_words = texture_words
        .iter()
        .filter(|word| looks_like_gp0_command_opcode(((**word) >> 24) as u8))
        .count();
    let primitive_pointer_words = words
        .iter()
        .skip(1)
        .filter(|word| looks_like_mapped_ram_pointer_word(**word))
        .count();

    Some(
        Gp0DrawBounds {
            min_x,
            max_x,
            min_y,
            max_y,
            has_visible_x,
            zero_vertices,
            zero_texture_words,
            command_like_texture_words,
            primitive_pointer_words,
        }
        .with_offset(drawing_offset),
    )
}

fn gp0_command_rect_dimensions(opcode: u8, words: &[u32]) -> Option<(i32, i32)> {
    match opcode {
        0x60..=0x63 if words.len() >= 3 => gp0_variable_rect_dimensions(words[2]),
        0x64..=0x67 if words.len() >= 4 => gp0_variable_rect_dimensions(words[3]),
        0x68..=0x6f => Some((1, 1)),
        0x70..=0x77 => Some((8, 8)),
        0x78..=0x7f => Some((16, 16)),
        _ => None,
    }
}

fn gp0_variable_rect_dimensions(word: u32) -> Option<(i32, i32)> {
    let width = (word & 0xffff) as i32;
    let height = (word >> 16) as i32;
    (width > 0 && height > 0).then_some((width, height))
}

fn looks_like_mapped_ram_pointer_word(value: u32) -> bool {
    matches!(value & 0xe000_0000, 0x8000_0000 | 0xa000_0000)
        && physical_address(value) < BR2_NATIVE_RAM_END
}

fn gp0_signed_xy(value: u32) -> (i32, i32) {
    (
        sign_extend_11_bits(value & 0x07ff),
        sign_extend_11_bits((value >> 16) & 0x07ff),
    )
}

fn gp0_drawing_offset_xy(value: u32) -> (i32, i32) {
    (
        sign_extend_11_bits(value & 0x07ff),
        sign_extend_11_bits((value >> 11) & 0x07ff),
    )
}

fn sign_extend_11_bits(value: u32) -> i32 {
    if value & 0x0400 != 0 {
        (value as i32) | !0x07ff
    } else {
        value as i32
    }
}

fn draw_primitive_count(counts: &[u32; 256]) -> u32 {
    counts
        .iter()
        .enumerate()
        .filter(|(opcode, _)| looks_like_draw_primitive_opcode(*opcode as u8))
        .fold(0u32, |total, (_, count)| total.saturating_add(*count))
}

fn recent_draw_primitive_writes(stats: &PrimitiveRamWriteStats) -> u64 {
    (0x20usize..=0x7f)
        .map(|opcode| {
            stats.current_vblank_opcode_counts[opcode]
                .saturating_add(stats.last_vblank_opcode_counts[opcode])
        })
        .fold(0u64, u64::saturating_add)
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct UnlinkedPrimitiveReplayDecision {
    enabled: bool,
    reason: &'static str,
    candidate_headers: usize,
    diagnostics: UnlinkedPrimitiveReplayDiagnostics,
}

impl UnlinkedPrimitiveReplayDecision {
    fn enabled(reason: &'static str, candidate_headers: usize) -> Self {
        Self {
            enabled: true,
            reason,
            candidate_headers,
            diagnostics: UnlinkedPrimitiveReplayDiagnostics::default(),
        }
    }

    fn disabled(reason: &'static str, candidate_headers: usize) -> Self {
        Self {
            enabled: false,
            reason,
            candidate_headers,
            diagnostics: UnlinkedPrimitiveReplayDiagnostics::default(),
        }
    }

    fn with_diagnostics(mut self, diagnostics: UnlinkedPrimitiveReplayDiagnostics) -> Self {
        self.diagnostics = diagnostics;
        self
    }
}

fn gpu_linked_list_command_ranges(commands: &[(u32, u32)]) -> Vec<std::ops::Range<usize>> {
    let words = commands
        .iter()
        .map(|(_, command)| *command)
        .collect::<Vec<_>>();
    gp0_command_ranges(&words)
}

fn gp0_command_ranges(words: &[u32]) -> Vec<std::ops::Range<usize>> {
    let mut ranges = Vec::new();
    let mut offset = 0;
    while offset < words.len() {
        let command_words = gp0_command_word_count(&words[offset..])
            .unwrap_or(1)
            .max(1)
            .min(words.len() - offset);
        ranges.push(offset..offset + command_words);
        offset += command_words;
    }
    ranges
}

fn zn_security_response_from_bios(rom: &[u8]) -> Option<Vec<u8>> {
    const LICENSE_OFFSET: usize = 0x0000_baa0;
    const RESPONSE_OFFSET: usize = 0x0000_b98d;

    let license = rom.get(LICENSE_OFFSET..)?;
    let license_len = license.iter().position(|byte| *byte == 0)?;
    if license_len < 2 {
        return None;
    }

    let response_len = license_len - 1;
    let response = rom.get(RESPONSE_OFFSET..RESPONSE_OFFSET.checked_add(response_len)?)?;
    Some(response.to_vec())
}

fn br2_stale_unlinked_primitive_scan_allowed() -> bool {
    std::env::var_os("BR2_NATIVE_ENABLE_STALE_UNLINKED_PRIMITIVE_SCAN").is_some()
        && std::env::var_os("BR2_NATIVE_DISABLE_STALE_UNLINKED_PRIMITIVE_REPLAY").is_none()
}

fn stale_gpu_dma_recent_header_stream_preconditions(
    current_vblank: u64,
    dma_vblank: u64,
    last_nodes: u32,
    last_nonempty_nodes: u32,
    recent_header_count: u64,
    recent_header_writes: u64,
) -> bool {
    if dma_vblank == 0
        || last_nodes == 0
        || last_nonempty_nodes > BR2_UNLINKED_PRIMITIVE_REPLAY_SPARSE_NODE_LIMIT
    {
        return false;
    }
    if current_vblank.saturating_sub(dma_vblank) < BR2_UNLINKED_PRIMITIVE_REPLAY_STALE_DMA_VBLANKS {
        return false;
    }

    recent_header_count >= u64::from(BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS)
        && recent_header_writes >= u64::from(BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS)
}

fn stale_gpu_dma_recent_header_replay_has_guarded_packet_signal(
    diagnostics: &UnlinkedPrimitiveReplayDiagnostics,
) -> bool {
    let ordered_otc_chain = diagnostics.otc_chain_start.is_some()
        && diagnostics.otc_chain_terminated
        && !diagnostics.otc_chain_hit_node_limit
        && !diagnostics.otc_chain_cycle_detected
        && diagnostics.otc_chain_packets >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        && diagnostics.otc_chain_words >= diagnostics.otc_chain_packets
        && diagnostics.otc_chain_playfield_draw_packets
            >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        && diagnostics.otc_chain_safe_playfield_draw_packets
            >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        && diagnostics.otc_chain_nodes >= diagnostics.otc_chain_nonempty_nodes
        && diagnostics.otc_chain_nonempty_nodes >= diagnostics.otc_chain_packets
        && diagnostics.recent_header_otc_ranges > 0
        && diagnostics.recent_header_otc_header_links > 0
        && diagnostics.raw_stream_replayed_packets == 0
        && diagnostics.raw_stream_replayed_words == 0;
    if ordered_otc_chain {
        return true;
    }

    let otc_pointer_guarded_packets = diagnostics.recent_header_otc_inserted
        >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        || diagnostics.recent_header_stale_body_inserted >= diagnostics.replayed_draw_packets;

    diagnostics.replayed_draw_packets >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        && (diagnostics.replayed_draw_packets as usize)
            <= BR2_UNLINKED_PRIMITIVE_REPLAY_STALE_HEADER_PACKET_LIMIT
        && diagnostics.replayed_draw_words >= diagnostics.replayed_draw_packets
        && diagnostics.replay_ordered_candidates >= diagnostics.replayed_draw_packets
        && diagnostics.recent_header_stale_body_draw_candidates
            >= BR2_UNLINKED_PRIMITIVE_REPLAY_MIN_DRAW_PACKETS
        && diagnostics.recent_header_otc_ranges > 0
        && diagnostics.recent_header_otc_header_links > 0
        && otc_pointer_guarded_packets
        && diagnostics.raw_stream_replayed_packets == 0
        && diagnostics.raw_stream_replayed_words == 0
        && diagnostics.replayed_min_address.is_some()
        && diagnostics.replayed_max_address.is_some()
}

fn stale_gpu_dma_replay_guarded_validation_allowed(
    include_recent_header_stale_body_scan: bool,
    used_latest_otc_chain: bool,
    diagnostics: &UnlinkedPrimitiveReplayDiagnostics,
) -> bool {
    (include_recent_header_stale_body_scan || used_latest_otc_chain)
        && stale_gpu_dma_recent_header_replay_has_guarded_packet_signal(diagnostics)
}

fn native_unlinked_primitive_replay_interval_override() -> Option<Option<u64>> {
    let value = std::env::var(BR2_UNLINKED_PRIMITIVE_REPLAY_INTERVAL_ENV).ok()?;
    parse_native_unlinked_primitive_replay_interval_override(&value)
}

fn native_replay_validation_debug_min_vblank() -> Option<u64> {
    std::env::var("BR2_NATIVE_REPLAY_VALIDATION_DEBUG_MIN_VBLANK")
        .ok()
        .and_then(|value| value.trim().parse::<u64>().ok())
}

fn parse_native_unlinked_primitive_replay_interval_override(value: &str) -> Option<Option<u64>> {
    let value = value.trim();
    if value.eq_ignore_ascii_case("off")
        || value.eq_ignore_ascii_case("false")
        || value.eq_ignore_ascii_case("disable")
        || value.eq_ignore_ascii_case("disabled")
        || value.eq_ignore_ascii_case("none")
        || value == "0"
    {
        return Some(None);
    }

    value
        .parse::<u64>()
        .ok()
        .map(|interval| if interval == 0 { None } else { Some(interval) })
}

fn cache_isolated_primitive_ram_write_passthrough_allowed() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        std::env::var_os("BR2_NATIVE_CACHE_ISOLATED_PRIMITIVE_RAM_WRITETHROUGH").is_some()
    })
}

fn ram_offset(address: u32, ram_len: usize, access_len: usize) -> Option<usize> {
    let physical = physical_address(address);
    if physical >= 0x0080_0000 || ram_len == 0 {
        return None;
    }

    let offset = physical as usize % ram_len;
    (offset + access_len <= ram_len).then_some(offset)
}

fn scratchpad_offset(address: u32, scratchpad_len: usize, access_len: usize) -> Option<usize> {
    let physical = physical_address(address);
    let base = 0x1f80_0000;
    if physical < base {
        return None;
    }

    let offset = (physical - base) as usize;
    (offset + access_len <= scratchpad_len).then_some(offset)
}

fn banked_rom_offset(
    address: u32,
    banked_rom_len: usize,
    access_len: usize,
    rom_bank: u8,
) -> Option<usize> {
    let physical = physical_address(address);
    let base = 0x1f00_0000;
    let window_len = 0x0080_0000;
    if !(base..base + window_len).contains(&physical) {
        return None;
    }

    let offset = rom_bank as usize * window_len as usize + (physical - base) as usize;
    (offset + access_len <= banked_rom_len).then_some(offset)
}

fn mapped_zn_board_address(address: u32) -> Option<u32> {
    let physical = physical_address(address);
    (zn_board_address(physical)).then_some(physical)
}

fn zn_board_address(physical: u32) -> bool {
    matches!(
        physical,
        0x1fa0_0000..=0x1fa0_0003
            | 0x1fa0_0100..=0x1fa0_0103
            | 0x1fa0_0200..=0x1fa0_0203
            | 0x1fa0_0300..=0x1fa0_0303
            | 0x1fa1_0000..=0x1fa1_0003
            | 0x1fa1_0100..=0x1fa1_0103
            | 0x1fa1_0200
            | 0x1fa1_0300
            | 0x1fa2_0000..=0x1fa2_0003
            | 0x1fa3_0000..=0x1fa3_0003
            | 0x1fa4_0000..=0x1fa4_0003
            | 0x1fa6_0000..=0x1fa6_0001
            | 0x1faf_0000..=0x1faf_07ff
            | 0x1fb0_0000
            | 0x1fb0_0004
            | 0x1fb2_0000..=0x1fb2_0007
    )
}

